function operationsEdgeStateForLane(lane = {}) {
    const text = `${lane.key || ""} ${lane.title || ""} ${lane.tone || ""}`.toLowerCase();
    if (text.includes("blocked") || text.includes("risk") || text.includes("gate")) return "blocked";
    if (text.includes("degraded")) return "degraded";
    if (text.includes("research") || text.includes("strategy") || text.includes("shadow")) return "shadow/context-only";
    if (text.includes("paper") || text.includes("execution")) return "locked";
    return "active";
}

function buildOperationsRoleSpine(connectivity) {
    const nodesByKey = new Map(asArray(connectivity.nodes).map((node) => [node.key, node]));
    return OPERATIONS_ROLE_SPINE.map((role) => {
        const nodes = asArray(role.node_keys).map((key) => nodesByKey.get(key)).filter(Boolean);
        const hasBlocked = nodes.some((node) => node.health === "blocked" || node.authority_flags?.length);
        const hasDegraded = nodes.some((node) => node.health === "degraded");
        const hasPending = nodes.some((node) => node.health === "pending");
        return {
            ...role,
            status: hasBlocked ? "blocked" : (hasDegraded ? "degraded" : (hasPending ? "pending" : "online")),
            node_count: nodes.length,
            nodes: nodes.map((node) => node.key)
        };
    });
}

function aggregateNodeHealth(nodes = []) {
    const list = asArray(nodes);
    const hasBlocked = list.some((node) => node.health === "blocked" || asArray(node.authority_flags).length);
    const hasDegraded = list.some((node) => node.health === "degraded");
    const hasPending = list.some((node) => node.health === "pending");
    const hasOnline = list.some((node) => ["online", "read-only", "local-only", "shadow-only", "supplemental"].includes(node.health));
    if (hasBlocked) return "blocked";
    if (hasDegraded) return "degraded";
    if (hasPending) return "pending";
    return hasOnline ? "online" : "pending";
}

function buildTeamHealthModel(connectivity) {
    const nodesByKey = new Map(asArray(connectivity.nodes).map((node) => [node.key, node]));
    return TEAM_HEALTH_ROLES.map((role) => {
        const nodes = asArray(role.node_keys).map((key) => nodesByKey.get(key)).filter(Boolean);
        const activeNode = nodes.find((node) => ["blocked", "degraded", "pending"].includes(node.health)) || nodes[0] || {};
        return {
            ...role,
            status: aggregateNodeHealth(nodes),
            node_count: nodes.length,
            nodes: nodes.map((node) => node.key),
            current: dashboardText(activeNode.expanded?.current_process || activeNode.purpose || activeNode.status, "No current process exported")
        };
    });
}

function buildSystemConnectivityModel(status = {}) {
    const backendMap = status.phase5_system_map || {};
    const backendNodes = asArray(backendMap.nodes);
    const nodes = backendNodes.length ? backendNodes : asArray(status.modules);
    const nodeModels = nodes.map((node, index) => {
        const details = flowNodeDetails(node);
        const authority = systemMapAuthorityLabel(node, details);
        const displayStatus = node.display_status || node.status || node.backend_status || "pending";
        const authorityFlags = [
            ["trade_approval", node.trade_approval_control_enabled],
            ["order_place", node.order_place_control_enabled],
            ["broker_write", node.broker_write_allowed],
            ["live_capital", node.live_capital_enabled],
            ["prediction_market_write", node.prediction_market_write_allowed],
            ["kill_switch_mutation", node.kill_switch_mutation_authority]
        ].filter(([, value]) => Boolean(value)).map(([key]) => key);
        return {
            id: node.key || `node_${index + 1}`,
            key: node.key || `node_${index + 1}`,
            label: dashboardText(node.label, node.key || "System node"),
            lane: dashboardText(node.lane, "Operations"),
            role: dashboardText(details.role, node.owner || "Qadam desk"),
            status: dashboardText(displayStatus, "pending"),
            health: normalizeModelHealth(displayStatus, authority),
            input: dashboardText(details.input, "Runtime state"),
            output: dashboardText(details.output, "Dashboard state"),
            purpose: dashboardText(node.purpose || node.current_process || details.role, "System node diagnostic"),
            authority,
            authority_flags: authorityFlags,
            public_safe: node.public_safe !== false,
            ui_inferred: Boolean(node.ui_inferred),
            counts: node.counts || {},
            blockers: asArray(node.blockers),
            expanded: {
                purpose: dashboardText(node.purpose || node.current_process || details.role, "System node diagnostic"),
                current_process: dashboardText(node.current_process, "No current process exported"),
                current_status: dashboardText(displayStatus, "pending"),
                latest_heartbeat: dashboardText(node.latest_heartbeat || node.last_heartbeat || node.generated_at || status.generated_at, "not exported"),
                dependencies: asArray(node.dependencies).length ? asArray(node.dependencies) : [dashboardText(node.lane, "Operations lane")],
                degraded_reasons: asArray(node.blockers).length
                    ? asArray(node.blockers)
                    : (normalizeModelHealth(displayStatus, authority) === "degraded" || normalizeModelHealth(displayStatus, authority) === "blocked"
                        ? [dashboardText(displayStatus, "not exported")]
                        : []),
                backend_status_path: dashboardText(node.backend_status_path, "not exported"),
                event_log_references: compactUnique([
                    node.backend_status_path,
                    node.artifact_id,
                    node.stage,
                    node.event_log_written ? "event log written" : null
                ]),
                handoff: dashboardText(node.handoff, "passes state"),
                related_dashboard_links: relatedDashboardLinksForNode(node.key)
            }
        };
    });
    const nodeByKey = new Map(nodeModels.map((node) => [node.key, node]));
    const lanes = asArray(backendMap.lanes).length
        ? asArray(backendMap.lanes).map((lane) => ({
            key: lane.key,
            title: dashboardText(lane.title, lane.key || "System lane"),
            summary: dashboardText(lane.summary, "No lane summary exported"),
            tone: normalizeModelHealth(lane.tone),
            node_keys: asArray(lane.node_keys).filter((key) => nodeByKey.has(key)),
            handoff: dashboardText(lane.handoff, "passes state")
        }))
        : [{
            key: "operations",
            title: "Operations",
            summary: "Current dashboard modules.",
            tone: "pending",
            node_keys: nodeModels.map((node) => node.key),
            handoff: "state becomes dashboard readout"
        }];
    const edges = lanes.flatMap((lane) => lane.node_keys.slice(0, -1).map((from, index) => ({
        from,
        to: lane.node_keys[index + 1],
        lane: lane.key,
        state: operationsEdgeStateForLane(lane),
        label: lane.handoff,
        authority_boundary: "read-only status edge"
    })));
    const sourcePosture = backendMap.source_posture || {};
    const feedClusters = buildOperationsFeedClusters(status, sourcePosture);
    const authorityViolations = nodeModels
        .filter((node) => node.authority_flags.length || node.public_safe === false || node.ui_inferred)
        .map((node) => node.key);
    return {
        id: "system_connectivity_model",
        source: backendNodes.length ? "phase5_system_map" : "modules_fallback",
        node_count: nodeModels.length,
        lane_count: lanes.length,
        nodes: nodeModels,
        lanes,
        edges,
        feed_clusters: feedClusters,
        authority_violations: authorityViolations,
	        overview_scope: {
	            placement: "control-plane",
	            canonical: true,
	            max_nodes: nodeModels.length,
	            node_keys: nodeModels.map((node) => node.key)
	        },
	        operations_scope: {
	            placement: "operations-diagnostics",
	            node_keys: nodeModels.map((node) => node.key),
	            edge_states: ["active", "shadow/context-only", "degraded", "locked", "blocked"]
	        },
	        team_health_scope: {
	            placement: "team-health-row",
	            role_keys: TEAM_HEALTH_ROLES.map((role) => role.key)
	        },
	        boundary: backendMap.boundary || "The system map is read-only and sanitized for the dashboard."
	    };
	}

function buildOperationsModel(status = {}, source = {}, sharedModels = {}) {
    const liveBridge = status.live_bridge || {};
    const d1Snapshot = status.d1_snapshot || {};
    const d0Shell = status.d0_shell || {};
    const processEvents = asArray(status.process_console);
    const forbiddenActions = asArray(status.forbidden_actions);
    const connectivity = sharedModels.system_connectivity_model || buildSystemConnectivityModel(status);
    const roleSpine = buildOperationsRoleSpine(connectivity);
    const teamHealth = buildTeamHealthModel(connectivity);
    const governance = sharedModels.governance_model || buildGovernanceModel(status);
    const communicationsAudit = governance.communications || {};
    const operatorInbox = governance.operator_inbox || {};
    const authorityFlags = collectAuthorityFlags(status);
    const readinessWarnings = collectReadinessWarnings(status);
    const moduleCounts = countBy(asArray(status.modules), "status");
    const pipelineSummary = asArray(status.source_pipeline_summary);
    const phase4 = phase4StrategyStatus(status);
    const phase7 = status.phase7_demo_proof || {};
    const killSwitch = status.phase5_kill_switch_ledger || status.phase5_kill_switch || {};
    const bridgeCache = liveBridge.cache_policy || {};
    const publisher = liveBridge.publisher || {};
    const brokenItems = [
        ...authorityFlags.map((flag) => `authority flag: ${flag}`),
        ...readinessWarnings.map((warning) => `readiness warning: ${warning}`),
        ...connectivity.authority_violations.map((key) => `map authority violation: ${key}`),
        ...pipelineSummary
            .filter((pipeline) => modelNumber(pipeline.missing_credential_count, 0) || modelNumber(pipeline.degraded_count, 0))
            .map((pipeline) => `${dashboardText(pipeline.pipeline)} pipeline degraded or missing credentials`),
        ...(processEvents.length ? [] : ["process console has no recent events"])
    ];
    const reviewGroups = [
        {
            id: "runtime_safety",
            title: "Runtime, bridge, and safety",
            summary: "Read-only bridge state, static fallback, exporter/cache posture, hard blocks, and kill-switch ledger.",
            status: brokenItems.length ? "degraded" : "online",
            count: 5 + forbiddenActions.length + brokenItems.length
        },
	        {
	            id: "team_data_plumbing",
	            title: "Operating team and data plumbing",
	            summary: "The hedge-fund team roles and intelligence feed clusters that move observations into review.",
	            status: connectivity.feed_clusters.some((cluster) => cluster.status === "blocked") ? "blocked" : "online",
	            count: teamHealth.length + connectivity.feed_clusters.length
	        },
	        {
	            id: "system_map_event_trail",
	            title: "System map diagnostics and event trail",
	            summary: "Canonical-map counts, handoff edge states, recent runtime events, and closed-loop logging rule.",
	            status: connectivity.authority_violations.length ? "blocked" : "online",
	            count: connectivity.node_count + processEvents.length
        },
        {
            id: "governance_comms_audit",
            title: "Governance, inbox, and communications audit",
            summary: "Fund Manager comments, Chief Operating Officer inbox items, approval records, weekly review state, and outbound-only Telegram notifications.",
            status: communicationsAudit.command_path_enabled || communicationsAudit.live_send_allowed_count || operatorInbox.telegram_command_authority ? "blocked" : "pending",
            count: modelNumber(governance.comments?.count, 0) + modelNumber(communicationsAudit.pending_queue_count, 0) + modelNumber(operatorInbox.open_item_count, 0) + asArray(governance.open_actions).length
        }
    ];
    return {
        id: "operations",
        label: "Operations",
        question: "Is the runtime, bridge, exporter, system map, and safety plumbing healthy?",
        tone: authorityFlags.length || connectivity.authority_violations.length ? "blocked" : (readinessWarnings.length ? "degraded" : "online"),
        summary: `${connectivity.node_count} system nodes; ${processEvents.length} process events; ${forbiddenActions.length} hard blocks; ${authorityFlags.length} authority flags.`,
        runtime: {
            status_source: source?.key || "unknown",
            generated_at: status.generated_at || null,
            schema_version: status.schema_version || null,
            live_bridge_status: liveBridge.status || "not exported",
            live_bridge_read_only: liveBridge.read_only !== false,
            allowed_methods: asArray(liveBridge.allowed_methods),
            forbidden_methods: asArray(liveBridge.forbidden_methods),
            endpoint: liveBridge.endpoint || "/api/cockpit-status",
            static_fallback: liveBridge.static_fallback || "/status/cockpit-status.json",
            d0_shell_status: d0Shell.status || "not exported",
            d1_snapshot_status: d1Snapshot.status || "not exported",
            public_safe: d1Snapshot.public_safe !== false,
            cache_mode: bridgeCache.mode || "not exported",
            cache_max_age_seconds: modelNumber(bridgeCache.max_age_seconds, 0),
            stale_after_seconds: modelNumber(bridgeCache.stale_after_seconds, 0),
            publisher_status: publisher.status || "not exported",
            signature_algorithm: publisher.signature_algorithm || "not exported",
            signature_configured: Boolean(publisher.signature_configured)
        },
        safety: {
            forbidden_action_count: forbiddenActions.length,
            authority_flags: authorityFlags,
            readiness_warnings: readinessWarnings,
            live_capital_enabled: Boolean(status.capital?.live_capital_enabled)
	        },
	        system_connectivity_model: connectivity,
	        role_spine: roleSpine,
	        team_health: teamHealth,
	        operations_review_groups: reviewGroups,
        model_dependencies: {
            system_connectivity_model: connectivity.id || "system_connectivity_model",
            governance_model: governance.id || "governance"
        },
        forbidden_actions: forbiddenActions.slice(0, 8).map((action) => ({
            key: dashboardText(action.key, "safety stop"),
            reason: dashboardText(action.reason, "No reason exported.")
        })),
        process_events: processEvents.slice(-6).map((event) => ({
            timestamp: event.timestamp || event.created_at || event.generated_at,
            message: dashboardText(event.message || event.event || event.status, "runtime event")
        })),
        communications_audit: {
            status: communicationsAudit.telegram_status || "not exported",
            pending_queue_count: modelNumber(communicationsAudit.pending_queue_count, 0),
            dry_run_message_count: modelNumber(communicationsAudit.dry_run_message_count, 0),
            failed_count: modelNumber(communicationsAudit.failed_count, 0),
            suppressed_count: modelNumber(communicationsAudit.suppressed_count, 0),
            live_send_allowed_count: modelNumber(communicationsAudit.live_send_allowed_count, 0),
            command_path_enabled_count: modelNumber(communicationsAudit.command_path_enabled_count, 0),
            command_path_enabled: Boolean(communicationsAudit.command_path_enabled),
            send_gate: communicationsAudit.send_gate || "not exported",
            boundary: communicationsAudit.boundary || "Telegram is outbound notify-only."
        },
        governance_audit: {
            comments: modelNumber(governance.comments?.count, 0),
            suggestions: modelNumber(governance.comments?.suggestion_count, 0),
            accepted: modelNumber(governance.comments?.accepted_count, 0),
            implemented: modelNumber(governance.comments?.implemented_count, 0),
            approval: governance.approvals?.strategy_approval_state || "missing",
            weekly_review: governance.review_packs?.weekly_review_pack_state || "not ready",
            open_actions: asArray(governance.open_actions).slice(0, 4),
            operator_inbox_open_items: modelNumber(operatorInbox.open_item_count, 0),
            operator_inbox_high_or_critical_items: modelNumber(operatorInbox.high_or_critical_item_count, 0),
            live_promotion: governance.live_promotion?.status || "not eligible",
            boundary: governance.boundary || "Governance notes only. No trade approval, order placement, or local secret access."
        },
        broken_summary: {
            status: brokenItems.length ? "degraded" : "online",
            item_count: brokenItems.length,
            items: brokenItems.slice(0, 8),
            authority_flag_count: authorityFlags.length,
            readiness_warning_count: readinessWarnings.length,
            degraded_pipeline_count: pipelineSummary.filter((pipeline) => modelNumber(pipeline.missing_credential_count, 0) || modelNumber(pipeline.degraded_count, 0)).length,
            map_authority_violation_count: connectivity.authority_violations.length
        },
        diagnostics: {
            module_health: {
                total: asArray(status.modules).length,
                online: modelNumber(moduleCounts.online || moduleCounts.ok || moduleCounts.ready || moduleCounts.read_only_ready, 0),
                degraded: modelNumber(moduleCounts.degraded, 0),
                blocked: modelNumber(moduleCounts.blocked, 0),
                pending: modelNumber(moduleCounts.pending, 0),
                local_only: modelNumber(moduleCounts.local_only || moduleCounts["local-only"], 0)
            },
            exporter_state: {
                status_source: source?.key || "unknown",
                generated_at: status.generated_at || null,
                runtime_copy: d1Snapshot.runtime_copy || "not exported",
                landing_copy: d1Snapshot.landing_copy || "not exported",
                cache_mode: bridgeCache.mode || "not exported",
                static_fallback: liveBridge.static_fallback || "/status/cockpit-status.json",
                signature_status: publisher.status || "not exported",
                signature_configured: Boolean(publisher.signature_configured)
            },
            phase_certification: {
                phase4_stage: phase4.stage || "not exported",
                phase4_certified: Boolean(phase4.phase4_certified),
                phase5_certified: Boolean(status.phase5_certification?.phase5_certified),
                phase6_certified: Boolean(status.phase6_certification?.phase6_certified),
                phase7_visibility: phase7.stage_status || phase7.status || "not exported",
                phase7_certified: Boolean(status.phase7_certification?.phase7_certified)
            },
            kill_switch: {
                status: killSwitch.status || "not exported",
                total_count: modelNumber(killSwitch.kill_switch_count, 0),
                active_count: modelNumber(killSwitch.active_kill_switch_count || killSwitch.active_count, 0),
                blocking_count: modelNumber(killSwitch.blocking_kill_switch_count || killSwitch.blocking_count, 0),
                event_log_written: Boolean(killSwitch.event_log_written)
            }
        },
        latest_event: latestItem(processEvents),
        empty_state: processEvents.length ? null : dashboardModelEmptyState("missing"),
        boundary: "Operations is read-only diagnostics. It is not shell access and cannot run commands."
    };
}

function buildGovernanceCommentTargets(status = {}) {
    const candidates = asArray(status.trade_layer?.candidates);
    const observedSignals = asArray(status.trade_layer?.watching);
    const phase7 = status.phase7_demo_proof || {};
    const firstCandidate = candidates[0] || {};
    const firstSignal = observedSignals[0] || {};
    return [
        {
            view: "Trades",
            target_type: firstCandidate.instrument ? "trade_candidate" : "module",
            target_key: firstCandidate.instrument || "trade_layer",
            label: firstCandidate.instrument ? `Trade candidate: ${firstCandidate.instrument}` : "Trade lifecycle board",
            helper: "Comment on candidate quality, risk checks, blocked reasons, staged paper state, or postmortem needs.",
            href: "#trades"
        },
        {
            view: "Evidence",
            target_type: firstSignal.source ? "signal" : "source",
            target_key: firstSignal.signal_id || firstSignal.source || "source_health",
            label: firstSignal.instrument ? `Observed signal: ${firstSignal.instrument}` : "Source health and provenance",
            helper: "Comment on source coverage, stale data, missing credentials, or provenance quality.",
            href: "#evidence"
        },
        {
            view: "Reasoning",
            target_type: "strategy",
            target_key: "strategy_lead",
            label: "Strategy Lead / reasoning chain",
            helper: "Comment on hypotheses, worldview priors, missing corroboration, or challenge quality.",
            href: "#reasoning"
        },
        {
            view: "Trades",
            target_type: phase7.postmortem_due_count ? "postmortem" : "system",
            target_key: phase7.postmortem_due_count ? "postmortem_due" : "phase7_demo_proof",
            label: phase7.postmortem_due_count ? "Postmortem due" : "60-day paper growth trial",
            helper: "Comment on paper growth, drawdown, maturity, postmortems, or paper-account interpretation.",
            href: "#trades"
        },
        {
            view: "Operations",
            target_type: "system",
            target_key: "operations_health",
            label: "Operations health",
            helper: "Comment on bridge, exporter, system map, module health, source clusters, or safety rails.",
            href: "#operations"
        },
        {
            view: "Operations",
            target_type: "strategy",
            target_key: "phase4_strategy_approval",
            label: "Approval and review records",
            helper: "Comment on approvals, weekly review packs, Telegram state, or live-promotion readiness.",
            href: "#operations"
        }
    ];
}

function governanceRecord(label, state, detail, tone = "pending", extras = {}) {
    return {
        label,
        state: dashboardText(state, "not exported"),
        detail: dashboardText(detail, "No detail exported."),
        tone,
        event_log_written: Boolean(extras.event_log_written),
        boundary: dashboardText(extras.boundary, "Audit record only. No authority is granted by display."),
        href: extras.href || "#operations"
    };
}

function buildGovernanceApprovalRecords(status = {}) {
    const phase4 = phase4StrategyStatus(status);
    const phase5Certification = status.phase5_certification || {};
    const phase6 = status.phase6_learning_loop || {};
    const phase6Certification = status.phase6_certification || {};
    const phase7 = status.phase7_demo_proof || {};
    const telegram = status.phase5_telegram_notifier || {};
    const livePromotion = status.phase7_live_promotion_review || {};
    return [
        governanceRecord(
            "Phase 4 strategy approval",
            phase4.approval_event_status || phase4.approval_event?.approval_state || "missing",
            phase4.approval_event?.boundary || phase4.boundary,
            phase4.approval_event_status === "approved" || phase4.approval_event?.approval_state === "approved" ? "online" : "blocked",
            {
                event_log_written: phase4.approval_event?.event_log_correlation_present,
                boundary: phase4.approval_event?.boundary || phase4.boundary,
                href: "#reasoning"
            }
        ),
        governanceRecord(
            "Phase 5 certification",
            phase5Certification.stage_status || phase5Certification.status || "not exported",
            phase5Certification.boundary,
            phase5Certification.phase5_certified ? "online" : "pending",
            {
                event_log_written: phase5Certification.event_log_written,
                boundary: phase5Certification.boundary,
                href: "#trades"
            }
        ),
        governanceRecord(
            "Phase 6 learning approval",
            phase6.approval_state || phase6Certification.approval_state || "not requested",
            `${phase6.pending_review_action_count || phase6Certification.pending_review_action_count || 0} pending review actions; ${phase6.explicitly_deferred_action_count || phase6Certification.explicitly_deferred_action_count || 0} explicitly deferred actions.`,
            (phase6.pending_review_action_count || phase6Certification.pending_review_action_count) ? "blocked" : "pending",
            {
                event_log_written: phase6.event_log_written || phase6Certification.event_log_written,
                boundary: phase6.boundary || phase6Certification.boundary,
                href: "#trades"
            }
        ),
        governanceRecord(
            "Weekly review pack",
            phase7.q7_16_weekly_review_pack_stage_allowed ? "allowed" : "not ready",
            `${phase7.weekly_proof_trade_target || 3} verified paper trades per week where qualified setups exist; ${phase7.closed_proof_trade_count || 0}/${phase7.mature_benchmark || 100} verified paper trades.`,
            phase7.q7_16_weekly_review_pack_stage_allowed ? "online" : "pending",
            {
                event_log_written: phase7.event_log_written,
                boundary: "Weekly review packs summarize backend paper-growth state only. They cannot force trades, mark performance as mature, or approve live promotion.",
                href: "#trades"
            }
        ),
        governanceRecord(
            "Live-promotion review workflow",
            livePromotion.status || (phase7.phase7_30_day_run_complete ? "planning visible" : "not eligible"),
            livePromotion.boundary || "Live promotion remains a review workflow only until paper-growth, maturity, drawdown, postmortem, and approval gates pass.",
            livePromotion.live_capital_enabled ? "blocked" : "pending",
            {
                event_log_written: livePromotion.event_log_written,
                boundary: livePromotion.boundary || "Live promotion review cannot enable live capital from the dashboard.",
                href: "#operations"
            }
        ),
        governanceRecord(
            "Telegram send-test approval",
            telegram.send_test_approval_present ? "present" : "missing",
            `${telegram.queued_dry_run_alert_count || 0} queued dry-run alerts; ${telegram.telegram_live_notifications_allowed_count || 0} live notifications allowed.`,
            telegram.telegram_live_notifications_allowed_count ? "blocked" : "pending",
            {
                event_log_written: telegram.event_log_written,
                boundary: telegram.boundary,
                href: "#operations"
            }
        )
    ];
}

function buildGovernanceOpenActions(status = {}) {
    const notes = status.fund_manager_notes || {};
    const phase6 = status.phase6_learning_loop || {};
    const phase7 = status.phase7_demo_proof || {};
    const telegram = status.phase5_telegram_notifier || {};
    const operatorInbox = status.operator_inbox || {};
    const actions = [];
    asArray(operatorInbox.recent_items)
        .filter((item) => item.status === "open")
        .slice(0, 3)
        .forEach((item) => {
            actions.push({
                label: dashboardText(item.summary, "Chief Operating Officer inbox item"),
                detail: dashboardText(item.required_action, "Review this Chief Operating Officer inbox item."),
                tone: item.severity === "critical" || item.severity === "high" ? "blocked" : "pending",
                href: item.dashboard_section === "Portfolio" ? "#trades" : item.dashboard_section === "Sources" ? "#evidence" : item.dashboard_section === "Reasoning" ? "#reasoning" : "#operations"
            });
        });
    if (modelNumber(notes.suggestion_count, 0)) {
        actions.push({
            label: "Review Fund Manager suggestions",
            detail: `${notes.suggestion_count} suggestions mirrored; ${notes.accepted_count || 0} accepted; ${notes.implemented_count || 0} implemented.`,
            tone: "pending",
            href: "#operations"
        });
    }
    if (modelNumber(phase6.governance_pending_count || phase6.pending_review_action_count, 0)) {
        actions.push({
            label: "Resolve learning governance",
            detail: `${phase6.governance_pending_count || phase6.pending_review_action_count} learning review actions remain visible or deferred.`,
            tone: "blocked",
            href: "#trades"
        });
    }
    if (modelNumber(phase7.postmortem_due_count, 0)) {
        actions.push({
            label: "Review postmortem due marker",
            detail: `${phase7.postmortem_due_count} postmortem due markers need governance review before learning changes.`,
            tone: "pending",
            href: "#trades"
        });
    }
    if (!phase7.q7_16_weekly_review_pack_stage_allowed) {
        actions.push({
            label: "Wait for weekly review pack eligibility",
            detail: "Weekly review pack export is not yet allowed by backend proof state.",
            tone: "pending",
            href: "#trades"
        });
    }
    if (!telegram.send_test_approval_present) {
        actions.push({
            label: "Telegram remains dry-run",
            detail: "No private send-test approval is present; outbound member messages stay queued or dry-run.",
            tone: "pending",
            href: "#operations"
        });
    }
    return actions.length ? actions : [{
        label: "No open governance actions exported",
        detail: "The dashboard status does not expose any governance action that requires attention.",
        tone: "online",
        href: "#operations"
    }];
}

function buildGovernanceModel(status = {}) {
    const notes = status.fund_manager_notes || {};
    const comments = asArray(notes.recent_comments);
    const telegram = status.communications?.telegram || {};
    const telegramNotifier = status.phase5_telegram_notifier || {};
    const telegramHumanBrief = status.communications?.telegram_human_brief || status.telegram_human_brief || {};
    const dailyLearningAutomation = status.communications?.daily_learning_automation || status.daily_learning_automation || {};
    const dailyLearningBrief = status.communications?.daily_telegram_learning_brief || status.daily_telegram_learning_brief || {};
    const operatorInbox = status.operator_inbox || {};
    const phase4 = phase4StrategyStatus(status);
    const phase6 = status.phase6_learning_loop || {};
    const phase6Certification = status.phase6_certification || {};
    const phase7 = status.phase7_demo_proof || {};
    const approvalRecords = buildGovernanceApprovalRecords(status);
    const openActions = buildGovernanceOpenActions(status);
    return {
        id: "governance",
        label: "Governance",
        question: "What comments, approvals, reviews, and communications need attention?",
        tone: openActions.some((action) => action.tone === "blocked") || asArray(phase4.certification?.certification_blockers).length ? "blocked" : "pending",
        summary: `${comments.length} recent comments; approval ${dashboardText(phase4.approval_event_status || phase4.approval_event?.approval_state, "missing")}; Telegram ${dashboardText(telegram.status, "not exported")}; ${openActions.length} open actions.`,
        comments: {
            count: comments.length,
            suggestion_count: modelNumber(notes.suggestion_count, 0),
            accepted_count: modelNumber(notes.accepted_count, 0),
            implemented_count: modelNumber(notes.implemented_count, 0),
            rejected_count: modelNumber(notes.rejected_count, 0),
            records: comments
        },
        approvals: {
            strategy_approval_state: phase4.approval_event_status || phase4.approval_event?.approval_state || "missing",
            strategy_approval_logged: Boolean(phase4.approval_event?.approval_logged || phase4.approval_logged),
            learning_approval_state: phase6.approval_state || phase6Certification.approval_state || "not requested",
            pending_review_action_count: modelNumber(phase6.pending_review_action_count || phase6Certification.pending_review_action_count, 0),
            records: approvalRecords
        },
        review_packs: {
            weekly_review_pack_state: phase7.q7_16_weekly_review_pack_stage_allowed ? "allowed" : "not ready",
            weekly_proof_trade_target: modelNumber(phase7.weekly_proof_trade_target, 3),
            current_proof_week_number: modelNumber(phase7.current_proof_week_number, 0),
            proof_week_count: modelNumber(phase7.proof_week_count, 5),
            closed_proof_trade_count: modelNumber(phase7.closed_proof_trade_count, 0),
            postmortem_due_count: modelNumber(phase7.postmortem_due_count, 0),
            boundary: "Weekly review packs summarize backend paper-growth state only. They cannot force trades, mark performance as mature, or approve live promotion."
        },
        live_promotion: {
            status: status.phase7_live_promotion_review?.status || "not eligible",
            review_workflow_visible: Boolean(status.phase7_live_promotion_review || phase7.phase7_30_day_run_complete),
            live_capital_enabled: Boolean(status.phase7_live_promotion_review?.live_capital_enabled || phase7.live_capital_enabled),
            boundary: status.phase7_live_promotion_review?.boundary || "Live promotion review cannot enable live capital from the dashboard."
        },
        communications: {
            telegram_status: telegram.status || "not exported",
            dry_run_message_count: modelNumber(telegram.dry_run_message_count, 0),
            human_brief_status: telegramHumanBrief.status || telegram.human_brief_status || "not exported",
            human_brief_message_specificity_score: modelNumber(telegramHumanBrief.message_specificity_score || telegram.human_brief_message_specificity_score, 0),
            daily_learning_automation_status: dailyLearningAutomation.status || telegram.daily_learning_automation_status || "not exported",
            daily_learning_brief_status: dailyLearningBrief.status || telegram.daily_learning_brief_status || "not exported",
            daily_learning_brief_message_specificity_score: modelNumber(dailyLearningBrief.message_specificity_score || telegram.daily_learning_brief_message_specificity_score, 0),
            pending_queue_count: modelNumber(telegram.pending_queue_count, 0),
            failed_count: modelNumber(telegram.failed_count, 0),
            suppressed_count: modelNumber(telegram.suppressed_count || telegramNotifier.suppressed_alert_count, 0),
            send_gate: telegram.send_gate || telegramNotifier.send_test_gate_state || "not exported",
            command_path_enabled: Boolean(telegramNotifier.telegram_command_path_enabled),
            command_path_enabled_count: modelNumber(telegramNotifier.telegram_command_path_enabled_count, 0),
            live_send_allowed_count: modelNumber(telegramNotifier.telegram_live_notifications_allowed_count || telegramNotifier.live_send_allowed_count, 0),
            recent_messages: asArray(telegram.recent_messages),
            active_message_classes: asArray(telegram.active_message_classes),
            boundary: telegram.boundary || telegramNotifier.boundary || status.communications?.boundary || "Telegram is outbound notify-only."
        },
        operator_inbox: {
            status: operatorInbox.status || "not exported",
            item_count: modelNumber(operatorInbox.item_count, 0),
            open_item_count: modelNumber(operatorInbox.open_item_count, 0),
            high_or_critical_item_count: modelNumber(operatorInbox.high_or_critical_item_count, 0),
            postmortem_due_item_count: modelNumber(operatorInbox.postmortem_due_item_count, 0),
            paper_trade_related_item_count: modelNumber(operatorInbox.paper_trade_related_item_count, 0),
            telegram_related_item_count: modelNumber(operatorInbox.telegram_related_item_count, 0),
            acknowledgement_count: modelNumber(operatorInbox.acknowledgement_count, 0),
            comment_count: modelNumber(operatorInbox.comment_count, 0),
            allowed_read_commands: asArray(operatorInbox.allowed_read_commands),
            recent_items: asArray(operatorInbox.recent_items),
            telegram_command_authority: Boolean(operatorInbox.telegram_command_authority),
            comment_can_approve_trades: Boolean(operatorInbox.comment_can_approve_trades),
            ack_can_approve_trades: Boolean(operatorInbox.ack_can_approve_trades),
            boundary: operatorInbox.boundary || "Chief Operating Officer inbox is read-only oversight."
        },
        comment_targets: buildGovernanceCommentTargets(status),
        open_actions: openActions,
        empty_state: comments.length ? null : dashboardModelEmptyState("missing", 0, {
            title: "No governance comments loaded",
            body: "No governance comments are loaded for this dashboard status yet.",
            tone: "neutral"
        }),
        boundary: notes.boundary || status.communications?.boundary || "Governance notes only. No trade approval, order placement, or local secret access."
    };
}

function normalizeMissionBrief(status = {}, models = {}) {
    const exported = status.mission_control?.mission_brief;
    if (exported && Array.isArray(exported.questions) && exported.questions.length) {
        return exported;
    }
    const sources = models.sources_model || {};
    const trades = models.trades_model || {};
    const reasoning = models.reasoning_model || {};
    const performance = models.performance_model || {};
    const safety = models.safety_model || {};
    const paper = performance.paper_account || {};
    const sourceCounts = sources.counts || {};
    const tradeCounts = trades.counts || {};
    const reasoningCounts = reasoning.counts || {};
    const currentBalance = modelNumber(paper.current_balance_gbp, modelNumber(status.capital?.current_balance_gbp, 0));
    const totalPnl = modelNumber(paper.total_pnl_gbp, modelNumber(status.capital?.realized_pnl_gbp, 0) + modelNumber(status.capital?.unrealized_pnl_gbp, 0));
    const authorityFlags = asArray(safety.authority_flags);
    const nextAction = tradeCounts.postmortem_due
        ? {
            label: "Review paper postmortems",
            href: "#trades",
            tone: "blocked",
            summary: `${tradeCounts.postmortem_due} postmortems are due before learning can update.`
        }
        : {
            label: tradeCounts.candidate ? "Review trade candidates" : "Continue monitoring",
            href: tradeCounts.candidate ? "#trades" : "#mission-control",
            tone: tradeCounts.candidate ? "pending" : "online",
            summary: tradeCounts.candidate
                ? `${tradeCounts.candidate} trade ideas are visible but still gated.`
                : "No urgent Fund Manager intervention is visible."
        };
    const question = (key, text, answer, tone, href, summary, metrics) => ({
        key,
        question: text,
        answer,
        tone,
        href,
        summary,
        metrics
    });
    return {
        schema_version: 1,
        status: "fallback",
        question_count: 7,
        summary: "Fallback seven-question Fund Manager brief.",
        questions: [
            question(
                "watching",
                "What is Qadam watching?",
                `${sourceCounts.online || 0}/${sourceCounts.total || 0} sources online.`,
                sources.tone || "pending",
                "#evidence",
                sources.summary || "Source health is loading.",
                [
                    { label: "Online sources", value: sourceCounts.online || 0 },
                    { label: "Total sources", value: sourceCounts.total || 0 },
                    { label: "Missing credentials", value: sourceCounts.missing_credentials || 0 }
                ]
            ),
            question(
                "thinking",
                "What is Qadam thinking about next?",
                `${reasoningCounts.hypotheses || 0} hypotheses and ${reasoningCounts.evidence_packets || 0} evidence packets.`,
                reasoning.tone || "pending",
                "#reasoning",
                "Reasoning packets are shadow-only until gates pass.",
                [
                    { label: "Hypotheses", value: reasoningCounts.hypotheses || 0 },
                    { label: "Evidence", value: reasoningCounts.evidence_packets || 0 },
                    { label: "Reviews", value: asArray(reasoning.review_chain).length }
                ]
            ),
            question(
                "forbidden",
                "What is Qadam forbidden from doing?",
                `${authorityFlags.length} authority flags; live capital and broker writes are off.`,
                authorityFlags.length ? "blocked" : "online",
                "#operations",
                "The dashboard, models, Telegram intake, data sources, and quantum oracle cannot approve or place trades.",
                [
                    { label: "Live capital", value: "off" },
                    { label: "Broker write", value: "off" },
                    { label: "Dashboard write", value: "off" }
                ]
            ),
            question(
                "considering",
                "Which trades are candidates or blocked?",
                `${tradeCounts.candidate || 0} candidates and ${tradeCounts.blocked || 0} blocked ideas.`,
                tradeCounts.candidate || tradeCounts.blocked ? "pending" : "online",
                "#trades",
                "A candidate is still only something Qadam is considering.",
                [
                    { label: "Observed", value: tradeCounts.observed_signal || 0 },
                    { label: "Candidates", value: tradeCounts.candidate || 0 },
                    { label: "Blocked", value: tradeCounts.blocked || 0 }
                ]
            ),
            question(
                "traded",
                "What has Qadam traded on paper?",
                `${tradeCounts.submitted_paper_order || 0} submitted paper orders and ${tradeCounts.open_position || 0} open positions.`,
                tradeCounts.submitted_paper_order || tradeCounts.open_position ? "online" : "pending",
                "#trades",
                "Paper activity is mirrored from local account state and does not imply live-capital authority.",
                [
                    { label: "Orders", value: tradeCounts.submitted_paper_order || 0 },
                    { label: "Open", value: tradeCounts.open_position || 0 },
                    { label: "Closed", value: tradeCounts.closed_paper_trade || 0 }
                ]
            ),
            question(
                "portfolio",
                "What is the portfolio worth?",
                `${formatMoney(currentBalance)} with ${formatMoney(totalPnl)} paper P&L.`,
                performance.tone || "online",
                "#trades",
                "Portfolio value is a read-only mirror of the paper account and local snapshots.",
                [
                    { label: "Balance", value: formatMoney(currentBalance) },
                    { label: "P&L", value: formatMoney(totalPnl) },
                    { label: "Postmortems due", value: tradeCounts.postmortem_due || 0 }
                ]
            ),
            question(
                "blocked",
                "Why is Qadam blocked or waiting?",
                nextAction.label,
                nextAction.tone,
                nextAction.href,
                nextAction.summary,
                [
                    { label: "Postmortems", value: tradeCounts.postmortem_due || 0 },
                    { label: "Authority flags", value: authorityFlags.length },
                    { label: "Candidates", value: tradeCounts.candidate || 0 }
                ]
            )
        ],
        navigation: [
            { key: "mission", label: "Mission", href: "#mission-control" },
            { key: "map", label: "Map", href: "#system-map" },
            { key: "sources", label: "Sources", href: "#evidence" },
            { key: "reasoning", label: "Reasoning", href: "#reasoning" },
            { key: "trades", label: "Trades", href: "#trades" },
            { key: "portfolio", label: "Portfolio", href: "#trades" },
            { key: "safety", label: "Safety", href: "#operations" },
            { key: "inbox", label: "Inbox", href: "#operations" },
            { key: "runtime", label: "Runtime", href: "#operations" }
        ],
        next_action: nextAction,
        authority: {
            live_capital_enabled: false,
            broker_write_allowed: false,
            dashboard_write_authority: false,
            telegram_command_authority: false,
            llm_execution_authority: false,
            quantum_execution_authority: false
        },
        boundary: "RS-8 Mission Brief is read-only. It cannot approve, place, modify, resize, close, fund, or verify performance credit for trades."
    };
}

function buildOverviewModel(status = {}, source = {}, sharedOperations = null, sharedModels = {}) {
    const sources = sharedModels.sources_model || buildSourcesModel(status);
    const trades = sharedModels.trades_model || buildTradesModel(status, { sources_model: sources });
    const reasoning = sharedModels.reasoning_model || buildReasoningModel(status);
    const performance = sharedModels.performance_model || buildPerformanceModel(status);
    const operations = sharedModels.operations_model || sharedOperations || buildOperationsModel(status, source, sharedModels);
    const edgeTracker = sharedModels.edge_tracker_model || buildEdgeTrackerModel(status);
    const missionBrief = normalizeMissionBrief(status, {
        sources_model: sources,
        trades_model: trades,
        reasoning_model: reasoning,
        performance_model: performance,
        operations_model: operations,
        safety_model: sharedModels.safety_model || operations.safety || {}
    });
    const phase7 = status.phase7_demo_proof || {};
    const paperLive = status.paper_live_certification || {};
    const activeAutomation = status.paperops_active_paper_trading_automation || {};
    const firstWeekMandate = status.paperops_first_week_paper_trade_mandate || {};
    const opportunityScan = status.paperops_opportunity_scan_cadence || {};
    const capital = status.capital || {};
    const tradeLayer = status.trade_layer || {};
    const phase4 = status.phase4_strategy || {};
    const missionStrategy = status.mission_control?.strategy || {};
    const unattendedArmed = Boolean(
        paperLive.paper_live_unattended_execution_delegation_enabled
            || activeAutomation.unattended_paper_execution_delegation_enabled
    );
    const freshSubmitCount = modelNumber(
        activeAutomation.paperops2_fresh_eligible_submit_record_count,
        0
    );
    const duplicateSubmitCount = modelNumber(
        activeAutomation.paperops2_duplicate_submit_record_count,
        0
    );
    const automationReason = dashboardText(
        paperLive.paper_live_unattended_execution_delegation_reason
            || activeAutomation.unattended_paper_execution_delegation_reason,
        "not armed"
    );
    const opportunityScanInterval = modelNumber(opportunityScan.opportunity_scan_interval_minutes, 20);
    const paperSubmitRunnerInterval = modelNumber(opportunityScan.paper_submit_runner_interval_minutes, 60);
    const opportunityScanStatus = opportunityScan.status || "not_run";
    const mandateTarget = modelNumber(firstWeekMandate.daily_target_trade_count, 0);
    const mandateSubmitted = modelNumber(firstWeekMandate.daily_submitted_count, 0);
    const mandateReady = modelNumber(firstWeekMandate.daily_ready_submit_count, 0);
    const mandateMinNotional = modelNumber(firstWeekMandate.minimum_notional_usd, 0);
    const mandateActive = Boolean(firstWeekMandate.active);
    const mandateTone = mandateActive
        ? (mandateSubmitted >= mandateTarget && mandateTarget ? "online" : "pending")
        : "pending";
    const opportunityScanTone = /invalid|blocked/i.test(opportunityScanStatus)
        ? "blocked"
        : (opportunityScan.twenty_minute_scan_ready ? "online" : "pending");
    const opportunityScanSummary = opportunityScan.recommended_next_action
        || `Refresh opportunity state every ${opportunityScanInterval} minutes; guarded paper submission stays on the ${paperSubmitRunnerInterval}-minute runner.`;
    const actionNeeded = [];
    if (sources.quorum.status !== "ok") actionNeeded.push("Review source quorum");
    if (trades.counts.postmortem_due > 0 || performance.paper_account.postmortem_due_count > 0) actionNeeded.push("Review due postmortem");
    if (operations.safety.authority_flags.length) actionNeeded.push("Investigate authority flag");
    if (operations.safety.readiness_warnings.includes("false_phase7_proof_credit")) actionNeeded.push("Reject false performance proof");
    if (!actionNeeded.length) actionNeeded.push("Continue monitoring");
    const demoProof = {
        completed_calendar_day_count: modelNumber(phase7.completed_calendar_day_count, 0),
        required_calendar_day_count: modelNumber(phase7.phase7_harness_day_count, 30),
        current_proof_week_number: modelNumber(phase7.current_proof_week_number, 0),
        proof_week_count: modelNumber(phase7.proof_week_count, 0),
        weekly_proof_trade_target: modelNumber(phase7.weekly_proof_trade_target, 3),
        qualified_setup_count: modelNumber(phase7.qualified_setup_count, 0),
        eligible_setup_count: modelNumber(phase7.eligible_setup_count, 0),
        candidate_setup_count: modelNumber(phase7.candidate_setup_count, 0),
        closed_proof_trade_count: modelNumber(phase7.closed_proof_trade_count, 0),
        mature_benchmark: modelNumber(phase7.mature_benchmark, 100),
        proof_state: phase7.proof_state || "not exported",
        proof_credit_allowed: Boolean(phase7.phase7_proof_credit_allowed)
            && modelNumber(phase7.closed_proof_trade_count, 0) >= modelNumber(phase7.mature_benchmark, 100)
            && modelNumber(phase7.completed_calendar_day_count, 0) >= modelNumber(phase7.phase7_harness_day_count, 30)
    };
    const paperPnl = performance.paper_account.total_pnl_gbp || 0;
    const reviewTone = actionNeeded[0] === "Continue monitoring" ? "online" : "blocked";
    const readouts = [
        {
            id: "sources",
            label: "Source health",
            state: `${sources.counts.online}/${sources.counts.total} online`,
            tone: sources.tone,
            summary: sources.summary
        },
        {
            id: "trade_path",
            label: "Trade path",
            state: `${trades.counts.candidate} trade ideas`,
            tone: trades.tone,
            summary: `${trades.counts.qualified_setup} potential setups; ${trades.counts.submitted_paper_order} submitted paper orders; ${trades.counts.postmortem_due} postmortems due.`
        },
        {
            id: "growth_trial",
            label: "Paper growth trial",
            state: `${formatMoney(performance.growth_trial.current_value_gbp || 0)}`,
            tone: performance.tone,
            summary: `${formatMoney(performance.growth_trial.starting_value_gbp || 100000)} to ${formatMoney(performance.growth_trial.target_value_gbp || 200000)} over ${performance.growth_trial.horizon_days || 60} days; ${formatMoney(paperPnl)} paper P&L.`
        },
        {
            id: "review_focus",
            label: "Needs review",
            state: actionNeeded[0],
            tone: reviewTone,
            summary: actionNeeded.join("; ")
        }
    ];
    const statusChips = [
        {
            id: "paper_growth",
            label: "Paper growth trial",
            value: `${formatMoney(performance.growth_trial.current_value_gbp || 0)}`,
            tone: performance.tone
        },
        {
            id: "automation",
            label: "Autonomous runner",
            value: unattendedArmed ? "Armed" : "Needs review",
            tone: unattendedArmed ? "online" : "blocked"
        },
        {
            id: "eligible_setups",
            label: "Potential setups",
            value: `${demoProof.eligible_setup_count}`,
            tone: demoProof.eligible_setup_count ? "online" : "pending"
        },
        {
            id: "candidates",
            label: "Trade ideas",
            value: `${trades.counts.candidate}`,
            tone: trades.counts.candidate ? "pending" : "online"
        },
        {
            id: "paper_orders",
            label: "Submitted paper orders",
            value: `${trades.counts.submitted_paper_order}`,
            tone: trades.counts.submitted_paper_order ? "online" : "pending"
        },
        {
            id: "postmortems",
            label: "Postmortems due",
            value: `${trades.counts.postmortem_due}`,
            tone: trades.counts.postmortem_due ? "blocked" : "online"
        }
    ];
    const nextReviewLinks = [
        {
            view_id: "trades",
            href: "#trades",
            label: "Review trades",
            reason: trades.counts.postmortem_due
                ? "A postmortem is due."
                : `${trades.counts.qualified_setup} potential setups and ${trades.counts.candidate} trade ideas.`
        },
        {
            view_id: "evidence",
            href: "#evidence",
            label: "Review evidence",
            reason: sources.quorum.status === "ok"
                ? "Source quorum is currently sufficient."
                : "Source quorum needs attention."
        },
        {
            view_id: "reasoning",
            href: "#reasoning",
            label: "Review reasoning",
            reason: `${reasoning.counts.hypotheses} hypotheses and ${reasoning.counts.evidence_packets} evidence packets.`
        },
        {
            view_id: "operations",
            href: "#operations",
            label: "Review operations",
            reason: operations.safety.authority_flags.length
                ? "Authority flags require review."
                : "Runtime is read-only from this dashboard."
        }
    ];
    const systemStatus = [
        {
            id: "mode",
            label: "Mode",
            value: status.mode === "paper" ? "Paper trading" : canonicalStatusLabel(status.mode, { fallback: "Mode unknown" }),
            tone: status.mode === "paper" ? "online" : "pending",
            summary: "The dashboard is showing paper-account operation only."
        },
        {
            id: "runtime",
            label: "Runtime",
            value: operations.runtime?.live_bridge_read_only === false ? "Review bridge" : "Read-only bridge",
            tone: operations.runtime?.live_bridge_read_only === false ? "blocked" : "online",
            summary: source?.key === "live_bridge"
                ? "Protected status endpoint is serving the dashboard."
                : "Sanitized status snapshot is serving the dashboard."
        },
        {
            id: "sources",
            label: "Sources",
            value: `${sources.counts.online}/${sources.counts.total} connected`,
            tone: sources.tone,
            summary: `${sources.quorum.replayed_source_count}/${sources.quorum.expected_source_count} required sources replayed; ${sources.counts.missing_credentials} credentials missing.`
        },
        {
            id: "trades",
            label: "Trade desk",
            value: `${trades.counts.candidate} trade ideas`,
            tone: trades.counts.postmortem_due ? "blocked" : (trades.counts.candidate ? "pending" : "online"),
            summary: `${trades.counts.observed_signal} observed signals, ${trades.counts.submitted_paper_order} submitted paper orders, ${trades.counts.open_position} open positions.`
        },
        {
            id: "automation",
            label: "Autonomous runner",
            value: unattendedArmed ? "Armed" : "Needs review",
            tone: unattendedArmed ? "online" : "blocked",
            summary: freshSubmitCount
                ? `${freshSubmitCount} fresh paper order can be submitted by the guarded ${paperSubmitRunnerInterval}-minute PaperOps runner.`
                : `${automationReason}; ${duplicateSubmitCount} already-submitted staged order protected by idempotency. The ${opportunityScanInterval}-minute scanner only refreshes candidate state.`
        },
        {
            id: "first_week_paper_mandate",
            label: "First-week paper mandate",
            value: mandateActive && mandateTarget ? `${mandateSubmitted}/${mandateTarget} today` : "Not active",
            tone: mandateTone,
            summary: mandateActive
                ? `${mandateReady} paper-only mandate slots remain ready; each slot targets at least ${formatUsd(mandateMinNotional)} notional through Alpaca Paper only.`
                : "The first-week paper-only trade mandate is outside its active calendar window."
        },
        {
            id: "opportunity_scan",
            label: "Opportunity scanner",
            value: `${opportunityScanInterval} min read-only`,
            tone: opportunityScanTone,
            summary: opportunityScanSummary
        },
        {
            id: "paper_submit",
            label: "Paper submit",
            value: paperLive.paper_live_submission_delegation_allowed
                ? "Fresh order ready"
                : (duplicateSubmitCount ? "No duplicate submit" : "Waiting"),
            tone: paperLive.paper_live_submission_delegation_allowed ? "pending" : "online",
            summary: paperLive.paper_live_submission_delegation_allowed
                ? `The next guarded ${paperSubmitRunnerInterval}-minute run may submit one fresh eligible Alpaca Paper order.`
                : `The ${opportunityScanInterval}-minute scanner cannot submit. Alpaca Paper execution remains guarded by fresh-order, duplicate-submit, and PaperOps checks.`
        }
    ];
    const sourceGroups = asArray(sources.pipelines).slice(0, 5).map((pipeline) => ({
        key: pipeline.pipeline,
        label: OPERATIONS_PIPELINE_LABELS[pipeline.pipeline] || dashboardText(pipeline.label, "Source group"),
        value: `${pipeline.online_count}/${pipeline.source_count} online`,
        tone: pipeline.status,
        summary: [
            pipeline.degraded_count ? `${pipeline.degraded_count} degraded` : null,
            pipeline.missing_credential_count ? `${pipeline.missing_credential_count} missing credentials` : null,
            pipeline.research_usable_count ? `${pipeline.research_usable_count} research usable` : "observation only",
            pipeline.signal_review_eligible_count ? `${pipeline.signal_review_eligible_count} signal-review eligible` : "not signal-review eligible",
            pipeline.order_authority_count ? `${pipeline.order_authority_count} order authority` : "0 order authority"
        ].filter(Boolean).join("; ")
    }));
    const sourceSummary = {
        label: "Evidence summary",
        state: `${sources.counts.online}/${sources.counts.total} sources online`,
        tone: sources.tone,
        research_usable_count: sources.counts.research_usable,
        signal_review_eligible_count: sources.counts.signal_review_eligible,
        order_authority_count: sources.counts.order_authority,
        missing_credential_count: sources.counts.missing_credentials,
        detail_view: "evidence",
        summary: "Decision record: Overview scope = source posture counts; Evidence owner = source rows and pipeline ledgers."
    };
    const missionStrategyFamilies = asArray(missionStrategy.strategy_families);
    const strategyToggles = asArray(phase4.strategy_toggles?.toggles);
    const tradingStrategies = missionStrategyFamilies.length
        ? missionStrategyFamilies.map((strategy) => ({
            key: strategy.key,
            label: dashboardText(strategy.label, strategy.key || "Strategy family"),
            value: strategy.qualified_setup ? "Qualified paper setup" : "Waiting",
            tone: strategy.qualified_setup ? "online" : "pending",
            rank: modelNumber(strategy.rank, 99),
            fit: strategy.fit || "review",
            fit_score: modelNumber(strategy.fit_score, 0),
            instrument: strategy.instrument || "strategy family",
            catalyst_focus: strategy.catalyst_focus || "Catalyst focus not exported",
            qadam_fit_reason: strategy.qadam_fit_reason || "Qadam fit reason not exported.",
            route_fit: strategy.route_fit || "route under review",
            current_state: strategy.current_state || strategy.setup_state || "watching_for_evidence",
            current_reason: strategy.current_reason || "No current PaperOps reason exported.",
            setup_state: strategy.setup_state || "not_currently_qualified",
            qualified_setup: Boolean(strategy.qualified_setup),
            side: strategy.side || "not_determined",
            notional_gbp: modelNumber(strategy.notional_gbp, 0),
            approval_state: strategy.approval_state || "not exported",
            toggle_state: strategy.toggle_state || "not exported",
            visible_in_cockpit: strategy.visible_in_cockpit !== false,
            event_log_required: false,
            execution_allowed: false,
            paper_order_allowed: false,
            broker_write_allowed: false,
            live_capital_enabled: false,
            boundary: "Strategy-family fit is context only; only guarded PaperOps can submit paper orders.",
            summary: strategy.qadam_fit_reason || "Visible to Qadam's research and risk workflow; not an order route."
        }))
        : strategyToggles.length
        ? strategyToggles.map((strategy) => ({
            key: strategy.strategy_key,
            label: dashboardText(strategy.label, strategy.strategy_key || "Strategy family"),
            value: strategy.approval_state === "approved" ? "Active for paper research" : "Needs review",
            tone: strategy.approval_state === "approved" ? "online" : "pending",
            approval_state: strategy.approval_state || "not exported",
            toggle_state: strategy.toggle_state || "not exported",
            visible_in_cockpit: Boolean(strategy.visible_in_cockpit),
            event_log_required: Boolean(strategy.event_log_required),
            execution_allowed: Boolean(strategy.execution_allowed),
            paper_order_allowed: Boolean(strategy.paper_order_allowed),
            broker_write_allowed: Boolean(strategy.broker_write_allowed),
            live_capital_enabled: Boolean(strategy.live_capital_enabled),
            boundary: strategy.boundary || "Strategy toggle visibility only; it cannot route execution.",
            summary: "Visible to Qadam's research and risk workflow; not an order route."
        }))
        : [{
            key: "strategy_status",
            label: "Strategy families",
            value: phase4.strategy_document_status === "validated" ? "Ready for review" : "Not exported",
            tone: phase4.strategy_document_status === "validated" ? "online" : "pending",
            approval_state: phase4.approval_event_status || "not exported",
            toggle_state: phase4.strategy_document_status || "not exported",
            visible_in_cockpit: false,
            event_log_required: false,
            execution_allowed: false,
            paper_order_allowed: false,
            broker_write_allowed: false,
            live_capital_enabled: false,
            boundary: phase4.boundary || phase4.no_execution_boundary || "Strategy-family metadata has not been exported in this snapshot.",
            summary: "Strategy-family metadata has not been exported in this snapshot."
        }];
    const latestLocalReview = asArray(reasoning.review_chain).find((review) => review.key === "research_analyst") || {};
    const latestStrategyReview = asArray(reasoning.review_chain).find((review) => review.key === "strategy_lead") || {};
    const latestSignalReview = asArray(reasoning.review_chain).find((review) => review.key === "signal_integrity") || {};
    const quantReview = reasoning.quant_annotation || {};
    const thoughtFeed = [
        {
            label: "Current focus",
            value: `${reasoning.counts.hypotheses} hypotheses under review`,
            tone: reasoning.tone,
            summary: `${reasoning.counts.evidence_packets} evidence packets and ${reasoning.counts.shadow_packets} research packets are feeding the review queue.`
        },
        {
            label: "Research Analyst",
            value: dashboardText(latestLocalReview.status, "No local review exported"),
            tone: latestLocalReview.status || "pending",
            summary: dashboardText(latestLocalReview.summary, "No local assessment is exported yet.")
        },
        {
            label: "Strategy Lead",
            value: dashboardText(latestStrategyReview.status, "No strategy review exported"),
            tone: latestStrategyReview.status || "pending",
            summary: dashboardText(latestStrategyReview.summary, "No Strategy Lead review is exported yet.")
        },
        {
            label: "Signal gate",
            value: dashboardText(latestSignalReview.status, "No signal review exported"),
            tone: latestSignalReview.status || "pending",
            summary: dashboardText(latestSignalReview.summary, "No signal-gate review is exported yet.")
        },
        {
            label: "Head of Quant",
            value: dashboardText(quantReview.recommendation, "hold"),
            tone: quantReview.status || "pending",
            summary: `${dashboardText(quantReview.backend, "quant model")} check; ${dashboardText(quantReview.boundary, "annotation only")}.`
        }
    ];
    const observedIdeas = asArray(tradeLayer.watching).map((item) => ({
        id: item.alert_id || item.intent_id || item.instrument || "observed_signal",
        label: item.instrument || item.symbol || "Observed signal",
        value: "Observed signal",
        tone: item.status || "pending",
        summary: item.trigger || item.chart_context || "Qadam is watching this market event."
    }));
    const candidateIdeas = asArray(tradeLayer.candidates).map((item) => ({
        id: item.intent_id || item.instrument || "candidate",
        label: item.instrument || item.strategy || "Candidate",
        value: "Candidate, not order",
        tone: item.status || "pending",
        summary: item.evidence_summary || item.catalyst || "Candidate needs review before any paper state."
    }));
    const blockedIdeas = asArray(tradeLayer.blocked).map((item) => ({
        id: item.intent_id || item.instrument || "blocked",
        label: item.instrument || item.strategy || "Blocked idea",
        value: "Blocked",
        tone: "blocked",
        summary: item.blocked_reason || item.risk_state || "Held by evidence, policy, or risk checks."
    }));
    const tradeConsiderations = [...observedIdeas, ...candidateIdeas, ...blockedIdeas].slice(0, 5);
    const reasoningSummary = {
        label: "Reasoning detail",
        state: `${reasoning.counts.hypotheses} hypotheses`,
        tone: reasoning.tone,
        research_goal_active_count: reasoning.counts.research_goal_active_count || reasoning.counts.research_goals || 0,
        evidence_packet_count: reasoning.counts.evidence_packets,
        shadow_packet_count: reasoning.counts.shadow_packets,
        detail_view: "reasoning",
        summary: "Overview keeps reasoning to Mission Snapshot context. Full hypotheses, priors, evidence packets, and reviews live in Reasoning."
    };
    const tradeStateSummary = {
        label: "Trade detail",
        state: `${trades.counts.candidate} candidates`,
        tone: trades.tone,
        observed_signal_count: trades.counts.observed_signal,
        candidate_count: trades.counts.candidate,
        blocked_count: trades.counts.blocked,
        submitted_paper_order_count: trades.counts.submitted_paper_order,
        open_position_count: trades.counts.open_position,
        closed_paper_trade_count: trades.counts.closed_paper_trade,
        postmortem_due_count: trades.counts.postmortem_due,
        detail_view: "trades",
        summary: "Decision record: Overview scope = lifecycle counts; Trades owner = signal rows, candidate lineage, paper-order records, and postmortems."
    };
    const paperTotal = modelNumber(
        capital.starting_balance_gbp,
        modelNumber(performance.paper_account.starting_balance_gbp, modelNumber(capital.current_balance_gbp, 100000))
    );
    const paperEquity = modelNumber(
        capital.equity_gbp ?? capital.current_balance_gbp,
        modelNumber(performance.paper_account.current_balance_gbp, paperTotal)
    );
    const paperCash = modelNumber(capital.cash_gbp, modelNumber(performance.paper_account.cash_gbp, paperEquity));
    const growthTrial = performance.growth_trial || {};
    const growthTarget = modelNumber(growthTrial.target_value_gbp, paperTotal * 2);
    const growthProgress = growthTarget > paperTotal
        ? Math.min(1, Math.max(0, (paperEquity - paperTotal) / (growthTarget - paperTotal)))
        : 0;
    const openExposure = asArray(capital.open_positions).reduce(
        (total, position) => total + modelNumber(position.notional_gbp ?? position.market_value_gbp ?? position.value_gbp, 0),
        0
    );
    const pendingExposure = [
        ...asArray(tradeLayer.staged_orders),
        ...asArray(tradeLayer.submitted_orders),
        ...asArray(capital.orders).filter((order) => !/filled|closed|cancelled|canceled/i.test(String(order.status || "")))
    ].reduce((total, order) => total + modelNumber(order.notional_gbp ?? order.risk_size_gbp ?? order.value_gbp, 0), 0);
    const deployedCapacity = openExposure + pendingExposure;
    const capacityUsedFraction = paperTotal ? Math.min(1, Math.max(0, deployedCapacity / paperTotal)) : 0;
    const paperCapacity = {
        total_gbp: paperTotal,
        equity_gbp: paperEquity,
        cash_gbp: paperCash,
        deployed_gbp: deployedCapacity,
        available_gbp: Math.max(0, paperTotal - deployedCapacity),
        used_fraction: capacityUsedFraction,
        used_pct: Math.round(capacityUsedFraction * 1000) / 10,
        total_pnl_gbp: performance.paper_account.total_pnl_gbp || 0,
        target_gbp: growthTarget,
        target_horizon_days: modelNumber(growthTrial.horizon_days, 60),
        target_progress_fraction: growthProgress,
        paper_live_operation_allowed: Boolean(growthTrial.operation_allowed),
        drawdown_pct: performance.paper_account.drawdown_pct || capital.drawdown_pct || 0,
        open_position_count: performance.paper_account.open_position_count || asArray(capital.open_positions).length,
        order_count: performance.paper_account.order_count || asArray(capital.orders).length,
        closed_trade_count: performance.paper_account.closed_paper_trade_count || asArray(capital.closed_trades).length,
        observed_at: capital.observed_at || status.generated_at || null,
        equity_curve: paperAccountEquityPoints(capital),
        tone: deployedCapacity ? "pending" : "online",
        summary: `${formatMoney(paperEquity)} current equity toward ${formatMoney(growthTarget)} target; ${formatMoney(deployedCapacity)} currently deployed from ${formatMoney(paperTotal)} starting paper capital.`
    };
    return {
        id: "overview",
        label: "Overview",
        question: "What is happening now?",
        tone: readouts.some((item) => item.tone === "blocked") ? "blocked" : (readouts.some((item) => item.tone === "degraded") ? "degraded" : "online"),
        summary: `${sources.counts.online}/${sources.counts.total} sources current; ${demoProof.eligible_setup_count} potential setups; ${trades.counts.candidate} trade ideas; ${opportunityScanInterval}-minute opportunity scan; ${formatMoney(paperEquity)} toward ${formatMoney(growthTarget)} in ${modelNumber(growthTrial.horizon_days, 60)} days; next review: ${actionNeeded[0]}.`,
        cards: readouts,
        readouts,
        mission_brief: missionBrief,
        status_chips: statusChips,
        review_focus: {
            state: actionNeeded[0],
            tone: reviewTone,
            summary: actionNeeded.join("; "),
            primary_href: nextReviewLinks[0]?.href || "#trades"
        },
        demo_proof: demoProof,
        system_status: systemStatus,
        data_sources_connected: sourceGroups,
        edge_tracker: edgeTracker,
        source_summary: sourceSummary,
        reasoning_summary: reasoningSummary,
        trade_state_summary: tradeStateSummary,
        detail_ledger_placement: {
            sources: "evidence",
            reasoning: "reasoning",
            trades: "trades",
            overview_scope: "summary_only"
        },
        opportunity_scan_cadence: {
            status: opportunityScanStatus,
            interval_minutes: opportunityScanInterval,
            frequency_per_hour: modelNumber(opportunityScan.opportunity_scan_frequency_per_hour, 3),
            model_review_interval_minutes: modelNumber(opportunityScan.model_review_interval_minutes, 60),
            paper_submit_runner_interval_minutes: paperSubmitRunnerInterval,
            recurring_scheduler_active: Boolean(opportunityScan.twenty_minute_recurring_scheduler_active),
            recurring_scheduler_status: opportunityScan.recurring_scheduler_status || "not_run",
            trade_submission_allowed_by_scan: Boolean(opportunityScan.trade_submission_allowed_by_scan),
            fresh_eligible_submit_count: modelNumber(opportunityScan.fresh_eligible_submit_count, 0),
            duplicate_submit_count: modelNumber(opportunityScan.duplicate_submit_count, 0),
            escalation_to_hourly_runner_recommended: Boolean(opportunityScan.escalation_to_hourly_runner_recommended),
            summary: opportunityScanSummary,
            boundary: opportunityScan.boundary || "The opportunity scanner is read-only and cannot submit orders."
        },
        native_strategy: missionStrategy.native_edge || null,
        strategy_family_count: modelNumber(missionStrategy.strategy_family_count, tradingStrategies.length),
        qualified_strategy_family_count: modelNumber(
            missionStrategy.qualified_strategy_family_count,
            tradingStrategies.filter((strategy) => strategy.qualified_setup).length
        ),
        strategy_decision_spine: asArray(missionStrategy.native_edge?.decision_spine),
        trading_strategies: tradingStrategies,
        thought_feed: thoughtFeed,
        trade_considerations: tradeConsiderations,
        paper_capacity: paperCapacity,
        lifecycle: trades.lifecycle,
        lifecycle_summary: `${trades.counts.qualified_setup} potential setups, ${trades.counts.candidate} trade ideas, ${trades.counts.submitted_paper_order} submitted paper orders, ${trades.counts.closed_paper_trade} closed paper trades.`,
        action_needed: actionNeeded,
        next_review_links: nextReviewLinks,
        mini_map: {
            source_model: "system_connectivity_model",
            placement: operations.system_connectivity_model.overview_scope.placement,
            node_keys: operations.system_connectivity_model.overview_scope.node_keys,
            health: operations.system_connectivity_model.authority_violations.length ? "blocked" : "online"
        },
        system_summary: "Live data -> Qadam Orchestrator -> model research -> quant/risk checks -> paper trading -> learning loop.",
        scope_note: "Mission Control shows readable state first; Diagnostics keeps raw evidence.",
        model_dependencies: {
            sources_model: sources.id || "sources",
            trades_model: trades.id || "trades",
            reasoning_model: reasoning.id || "reasoning",
            performance_model: performance.id || "performance",
            operations_model: operations.id || "operations",
            system_connectivity_model: operations.system_connectivity_model?.id || "system_connectivity_model"
        },
        boundary: "Overview is a read-only triage surface. It cannot approve, place, modify, close, fund, or verify performance credit for trades."
    };
}

const STAGE7_LEVEL1_SECTIONS = [
    "paper_fund_status",
    "source_intelligence_network",
    "watched_markets_universe",
    "strategy_playbook",
    "hedge_fund_investment_team",
    "hypotheses_pattern_recognition",
    "backtesting_learning_loop"
];

function stage7PlainState(status, fallback = "Waiting") {
    const text = dashboardText(status, fallback);
    if (/blocked|failed|halt/i.test(text)) return "Blocked";
    if (/degraded|missing|stale|drift|review/i.test(text)) return "Needs attention";
    if (/pending|waiting|not_due|not ready|deferred|idle/i.test(text)) return "Waiting";
    if (/optional|local only/i.test(text)) return "Optional";
    if (/read.only|readonly|paper|ok|ready|connected|online|sent|tracking|passed/i.test(text)) return "OK";
    return text;
}

function stage7ToneForState(state) {
    if (/blocked/i.test(state)) return "blocked";
    if (/needs attention/i.test(state)) return "degraded";
    if (/waiting|optional/i.test(state)) return "pending";
    return "online";
}

function stage7StatusRecord(id, label, sourceState, summary, consequence = null) {
    const state = consequence || stage7PlainState(sourceState);
    return {
        id,
        label,
        state,
        tone: stage7ToneForState(state),
        source_state: dashboardText(sourceState, "not exported"),
        summary: dashboardText(summary, "No summary exported."),
        proof_scope: "read_only_status"
    };
}

function stage7BuildNode(key, role, plainLabel, question, sourceState, current, handoff, authority = "Read-only status only.") {
    const state = stage7PlainState(sourceState);
    return {
        key,
        role,
        plain_label: plainLabel,
        question,
        state,
        tone: stage7ToneForState(state),
        source_state: dashboardText(sourceState, "not exported"),
        current: dashboardText(current, "No current activity exported."),
        handoff: dashboardText(handoff, "Passes sanitized state to the next gate."),
        authority: dashboardText(authority, "Read-only visibility only.")
    };
}

function stage7TradeBoardRow(item = {}, fallback = {}) {
    const instrument = item.instrument || item.symbol || item.asset || item.ticker || fallback.instrument || "Market idea";
    const gate = item.current_gate || item.gate || item.status || item.risk_state || fallback.gate || "watching";
    const state = stage7PlainState(gate);
    return {
        id: item.intent_id || item.signal_id || item.alert_id || item.order_id || item.id || `${fallback.stage || "stage"}_${instrument}`,
        instrument,
        domain: item.domain || item.strategy || item.asset_class || fallback.domain || "Qadam watchlist",
        thesis: item.thesis || item.evidence_summary || item.trigger || item.chart_context || item.catalyst || item.summary || fallback.thesis || "Qadam is watching for evidence before this can move.",
        gate: dashboardText(gate, "watching"),
        state,
        tone: stage7ToneForState(state),
        quality: item.quality_label || item.confidence_label || item.source_quorum_status || item.status || fallback.quality || "under review",
        blocker: item.blocked_reason || item.reason || item.risk_reason || item.next_condition || fallback.blocker || "No blocker exported.",
        paper_capacity_effect: item.notional_gbp || item.risk_size_gbp || item.value_gbp || fallback.paper_capacity_effect || null
    };
}

function stage7BoardColumn(key, label, rows, summary) {
    return {
        key,
        label,
        count: asArray(rows).length,
        rows: asArray(rows).slice(0, 4),
        summary,
        authority: "Read-only decision-state board. It cannot place or approve trades."
    };
}

function buildStage7TradeBoard(status = {}, trades = {}, overview = {}) {
    const tradeLayer = status.trade_layer || {};
    const lifecycle = trades.lifecycle || {};
    const lifecycleRecords = asArray(trades.lifecycle_records || lifecycle.records);
    const observed = asArray(tradeLayer.watching).map((item) => stage7TradeBoardRow(item, {
        stage: "watching",
        gate: "watching",
        quality: "source observation"
    }));
    const evidenceForming = [
        ...asArray(status.evidence_packets).slice(0, 2),
        ...asArray(status.shadow_packets).slice(0, 2)
    ].map((item) => stage7TradeBoardRow(item, {
        stage: "evidence",
        instrument: item.instrument || item.signal_id || "Evidence packet",
        domain: item.packet_type || "evidence",
        thesis: item.summary || item.packet_role || "Evidence is being normalized before strategy review.",
        gate: item.status || "evidence forming",
        quality: `${item.item_count || 0} evidence items`
    }));
    const candidates = asArray(tradeLayer.candidates).map((item) => stage7TradeBoardRow(item, {
        stage: "candidate",
        gate: "candidate"
    }));
    const riskReview = [
        ...asArray(tradeLayer.blocked),
        ...asArray(status.risk_agent?.reviews).slice(0, 2),
        ...asArray(status.signal_integrity?.reviews).slice(0, 2)
    ].map((item) => stage7TradeBoardRow(item, {
        stage: "risk",
        gate: item.blocked_reason ? "blocked" : "risk or quant review",
        quality: item.risk_state || item.status || "risk review",
        blocker: item.blocked_reason || item.summary || "Waiting for risk, signal, or quant confirmation."
    }));
    const paperOrders = [
        ...asArray(tradeLayer.staged_orders),
        ...asArray(tradeLayer.submitted_orders),
        ...asArray(status.capital?.orders).filter((order) => !/filled|closed|cancelled|canceled/i.test(String(order.status || ""))).slice(0, 3)
    ].map((item) => stage7TradeBoardRow(item, {
        stage: "paper_order",
        gate: item.status || "paper order state",
        quality: "Alpaca Paper only"
    }));
    const positions = asArray(status.capital?.open_positions).map((item) => stage7TradeBoardRow(item, {
        stage: "position",
        gate: item.status || "open position",
        thesis: "Open paper position mirrored from Alpaca Paper.",
        quality: "paper mirror"
    }));
    const postmortems = asArray(status.capital?.closed_trades).slice(0, 4).map((item) => stage7TradeBoardRow(item, {
        stage: "postmortem",
        gate: item.postmortem_status || "postmortem due",
        thesis: item.close_reason || "Closed paper trade awaiting learning review.",
        quality: "learning loop"
    }));

    const columns = [
        stage7BoardColumn("watching", "Watching", observed, "Raw observations and market signals Qadam is tracking."),
        stage7BoardColumn("evidence_forming", "Evidence forming", evidenceForming, "Evidence packets and shadow packets before strategy review."),
        stage7BoardColumn("candidate", "Candidate", candidates, "Ideas that reached candidate state but are still not orders."),
        stage7BoardColumn("risk_quant_review", "Risk / quant review", riskReview, "Risk, signal integrity, and quant review state."),
        stage7BoardColumn("paper_order", "Paper order", paperOrders, "Staged or submitted Alpaca Paper state only."),
        stage7BoardColumn("position_exit", "Position / exit", positions, "Open paper positions and exit monitoring."),
        stage7BoardColumn("postmortem", "Postmortem", postmortems, "Closed paper trade records feeding learning review.")
    ];
    return {
        columns,
        column_count: columns.length,
        active_idea_count: columns.reduce((total, column) => total + column.count, 0),
        summary: overview.lifecycle_summary || `${trades.counts?.candidate || 0} candidates and ${trades.counts?.open_position || 0} open positions are visible.`,
        paper_order_authority: false,
        broker_write_allowed: false,
        live_capital_enabled: false
    };
}

function stage7SourceGroups(status = {}, sources = {}) {
    const sourceLedger = asArray(
        status.mission_control?.data_sources?.ledger
            || status.data_sources?.ledger
            || status.source_registry?.ledger
            || status.watching
    );
    const pipelineLabels = {
        conflict: "Conflict & Geopolitics",
        physical: "Physical World Signals",
        macro: "Macro & Trade Data",
        market: "Markets & Technical Analysis",
        social: "Social News & Filings"
    };
    const pipelineDescriptions = {
        conflict: "War, security, blockade, escalation, and geopolitical-risk feeds.",
        physical: "Physical-world movement, fire, shipping, aviation, satellite, and infrastructure signals.",
        macro: "Rates, trade, inflation, commodities, industrial, and official economic context.",
        market: "Prices, technical analysis, order-flow, prediction-market, and broker mirror context.",
        social: "News, filings, social chatter, patents, code activity, and political-trading context."
    };
    const sourceDescriptions = {
        acled: "Tracks conflict events and political violence that can move oil, defence, and prediction-market probabilities.",
        ucdp: "Adds independent conflict-history context so Qadam can check whether a geopolitical signal is isolated or persistent.",
        gdelt: "Scans global news tone and event coverage for early signs of geopolitical, semiconductor, and defence catalysts.",
        oref: "Monitors Israel alert context that can matter for regional escalation and oil-risk hypotheses.",
        conflict_tracker: "Summarises major conflict zones so Qadam can keep geopolitical risk in context.",
        nasa_firms: "Detects fires and heat anomalies that can reveal physical disruption before prices react.",
        aviationstack: "Tracks flight movement and route disruption as a physical-world stress signal.",
        ais_maritime: "Tracks vessel movement and shipping disruption, especially around oil chokepoints.",
        arcgis_usace: "Adds geospatial and infrastructure context for ports, waterways, and physical bottlenecks.",
        space_track_celestrak: "Tracks satellite and orbital context that can support physical-world and defence hypotheses.",
        gps_jamming: "Flags navigation interference that can point to regional conflict or maritime disruption.",
        internet_outage: "Tracks internet disruption that can indicate civil unrest, conflict, or infrastructure stress.",
        fred: "Adds official US macro series for rates, liquidity, inflation, and commodity context.",
        bls: "Adds labour and inflation context that can affect macro-sensitive assets.",
        bis: "Adds global banking and credit context for macro stress and liquidity hypotheses.",
        ecb: "Adds European macro and liquidity context relevant to rates, FX, commodities, and risk appetite.",
        un_comtrade: "Tracks trade flows and import-export pressure in energy, metals, semiconductors, and defence supply chains.",
        usgs: "Adds minerals and resource context for metals, semiconductors, and industrial supply-chain hypotheses.",
        unusual_whales: "Optional options-flow context that is currently disabled unless reselected.",
        polymarket: "Tracks prediction-market probabilities and order-book context where public odds may diverge from Qadam's evidence.",
        kalshi: "Kalshi is connected through OddsPipe, which gives Qadam read-only normalized Kalshi/Polymarket markets, OHLCV context, and cross-platform spreads while direct Kalshi account access remains deferred.",
        hyperliquid: "Tracks crypto and perpetual-market stress where cross-asset risk can surface early.",
        alpaca: "Mirrors paper broker account, orders, positions, and market data for paper-only execution visibility.",
        rapidapi: "Intentionally disabled marketplace slot. No RapidAPI key is needed unless Qadam later selects a specific RapidAPI-backed provider.",
        coinglass: "Future optional derivatives-positioning adapter. No CoinGlass key is needed until Qadam explicitly promotes crypto/perps context.",
        chainlink: "Future optional price-feed cross-check. No RPC key is needed until a read-only adapter is built and approved.",
        bookmap: "Reads local order-flow context when a local bridge is available; it cannot place orders.",
        tradingview_mcp: "Provides read-only technical-analysis context from the local TradingView MCP adapter.",
        tradingview_paid_alerts: "Receives paid TradingView alert observations without execution authority.",
        rss: "Collects news and public feeds for broad event coverage.",
        telegram: "Captures user-submitted observations and bot communications as read-only context.",
        twitter_x: "Tracks public social/news velocity that can corroborate or challenge live hypotheses.",
        reddit: "Reddit Narrative Proxy reads ApeWisdom aggregate retail/forum attention while Reddit OAuth remains an optional upgrade.",
        sec_edgar: "Reads company filings for semiconductor, defence, and market-sensitive disclosures.",
        stock_act: "Reads Capitol Trades/STOCK Act congressional disclosures through the Apify Capitol Trades Scraper as political-trading context. It is evidence only, not trade authority.",
        patents: "Tracks patent activity for supply-chain, defence, and semiconductor innovation signals.",
        github: "Future optional developer and supply-chain activity adapter. No GitHub token is needed until a narrow watchlist and signal role are selected."
    };
    const watchingByKey = new Map(asArray(status.watching).map((source) => [source.source_key || source.key, source]));
    const optionalGapByKey = new Map(asArray(status.mission_control?.data_sources?.optional_source_gap_records)
        .map((gap) => [gap.source_key || gap.key, gap]));
    const coveredProxyByKey = new Map(asArray(status.mission_control?.data_sources?.covered_proxy_source_records)
        .map((record) => [record.source_key || record.key, record]));
    const candidatePatterns = asArray(status.daily_edge_findings_brief?.patterns_observed).length
        ? asArray(status.daily_edge_findings_brief.patterns_observed)
        : asArray(status.edge_pattern_ledger?.patterns || status.pattern_recognition_engine?.candidate_patterns);
    const sourceInfluenceMap = candidatePatterns.reduce((acc, pattern) => {
        const sourceKeys = asArray(pattern.source_families_involved || pattern.sources || pattern.source_keys);
        sourceKeys.forEach((sourceKey) => {
            if (!sourceKey) return;
            const market = pattern.market_sleeve || pattern.sleeve_label || pattern.sleeve_key || "market";
            const label = `${dashboardText(market)} pattern review`;
            const existing = acc.get(sourceKey) || [];
            existing.push({
                label,
                market,
                observation: pattern.observed_relationship || pattern.lead_lag_or_divergence_hypothesis || pattern.trading_strategy_implication || "Qadam is testing whether this source helps explain a watched-market move."
            });
            acc.set(sourceKey, existing);
        });
        return acc;
    }, new Map());
    const sourceStatusLabel = (source) => {
        const sourceKey = source.source_key || source.key;
        const status = String(source.status || source.readiness || "").toLowerCase();
        const credentialStatus = String(source.credential_status || "").toLowerCase();
        const selectionStatus = String(source.selection_status || "").toLowerCase();
        const actionCategory = String(source.action_category || "").toLowerCase();
        const readiness = String(source.readiness || "").toLowerCase();
        const registryStatus = String(source.registry_status || source.raw_status || "").toLowerCase();
        const providerStatus = String(source.provider_decision_status || source.provider_activation_state || "").toLowerCase();
        const providerDecisionText = `${readiness} ${registryStatus} ${providerStatus} ${selectionStatus} ${actionCategory}`;
        if (coveredProxyByKey.has(sourceKey)) return "Connected";
        if (actionCategory === "intentionally_disabled" || selectionStatus === "optional_disabled" || /marketplace disabled|intentionally disabled/.test(providerDecisionText)) return "Optional Disabled";
        if (actionCategory === "needs_adapter" || registryStatus === "needs_adapter" || /adapter not built|pending adapter|pending public adapter|optional adapter/.test(providerDecisionText)) return "Future Adapter";
        if (/provider decision required|provider selected/.test(providerDecisionText) && credentialStatus === "not_required") return "Provider Decision";
        if (optionalGapByKey.has(sourceKey) || credentialStatus === "missing_optional") return "Optional Gap";
        if (/online|ok|ready|connected|configured/.test(status)) return "Connected";
        if (/missing|credential/.test(credentialStatus) && optionalGapByKey.has(sourceKey)) return "Optional Gap";
        return "Degraded";
    };
    const statusTone = (label) => label === "Connected"
        ? "online"
        : (["Optional Gap", "Optional Disabled", "Future Adapter", "Provider Decision"].includes(label) ? "pending" : "degraded");
    const sourceLastUpdate = (source) => {
        const watching = watchingByKey.get(source.source_key || source.key) || {};
        return source.last_payload_time || source.last_heartbeat || watching.last_payload_time || watching.last_heartbeat || status.generated_at || "not exported";
    };
    const sourceContribution = (source) => {
        const sourceKey = source.source_key || source.key;
        return sourceDescriptions[sourceKey]
            || dashboardText(source.coverage_role || source.role, pipelineDescriptions[source.pipeline] || "Observation input for Qadam's research process.");
    };
    const sourceObservation = (source, influenceRecords = []) => {
        if (influenceRecords.length) {
            const markets = [...new Set(influenceRecords.map((item) => dashboardText(item.market)).filter(Boolean))].slice(0, 3).join(", ");
            return `${dashboardText(source.source_name || source.name || source.source_key)} is currently feeding ${markets || "a watched-market"} review: ${dashboardText(influenceRecords[0].observation)}`;
        }
        const gap = optionalGapByKey.get(source.source_key || source.key);
        if (gap) return `${dashboardText(source.source_name || source.name || source.source_key)} is an optional gap: ${dashboardText(gap.next_action, "credentials or provider access are still needed before it can contribute.")}`;
        const proxyCoverage = coveredProxyByKey.get(source.source_key || source.key);
        if (proxyCoverage) return `${dashboardText(proxyCoverage.proxy_coverage_name, "Reddit Narrative Proxy")} is connected as aggregate retail-attention context. ${dashboardText(proxyCoverage.next_action, "Reddit OAuth remains optional.")}`;
        const label = sourceStatusLabel(source);
        if (label === "Optional Disabled") return `${dashboardText(source.source_name || source.name || source.source_key)} is intentionally disabled. It is not a failed connection and does not need credentials for the current paper-trading core.`;
        if (label === "Future Adapter") return `${dashboardText(source.source_name || source.name || source.source_key)} is a future optional adapter. It is not connected because Qadam has not promoted this source into the live evidence set yet.`;
        if (label === "Provider Decision") return `${dashboardText(source.source_name || source.name || source.source_key)} is a provider-decision slot. Qadam has recorded the possible provider, but it is not part of the live source quorum yet.`;
        return `${dashboardText(source.source_name || source.name || source.source_key)} last reported ${sourceStatusLabel(source).toLowerCase()} and contributes: ${sourceContribution(source)}`;
    };
    const grouped = sourceLedger.reduce((acc, source) => {
        const key = source.pipeline || source.pipeline_key || "other";
        acc[key] = acc[key] || [];
        acc[key].push(source);
        return acc;
    }, {});
    const preferredOrder = ["conflict", "physical", "macro", "market", "social"];
    const orderedKeys = sourceLedger.length
        ? preferredOrder
        : [
            ...preferredOrder.filter((key) => grouped[key]),
            ...Object.keys(grouped).filter((key) => !preferredOrder.includes(key)).sort()
        ];
    const groups = orderedKeys.map((key) => {
        const records = grouped[key] || [];
        const normalizedSources = records.map((source) => {
            const sourceKey = source.source_key || source.key || source.source_name || "source";
            const influenceRecords = sourceInfluenceMap.get(sourceKey) || [];
            const statusLabel = sourceStatusLabel(source);
            return {
                key: sourceKey,
                name: dashboardText(source.source_name || source.name, sourceKey),
                status: source.status || source.readiness || "pending",
                status_label: statusLabel,
                status_tone: statusTone(statusLabel),
                readiness: source.readiness || source.credential_status || "not exported",
                last_update: sourceLastUpdate(source),
                description: sourceContribution(source),
                currently_influencing: influenceRecords.length ? influenceRecords[0].label : "",
                influencing_hypotheses: [...new Set(influenceRecords.map((item) => item.label))],
                recent_observation: sourceObservation(source, influenceRecords),
                operator_action: source.operator_action || coveredProxyByKey.get(sourceKey)?.next_action || optionalGapByKey.get(sourceKey)?.next_action || "none",
                eligible_for_signal_review: source.eligible_for_signal_review === true,
                usable_for_research_context: source.usable_for_research_context !== false
            };
        });
        const connectedCount = normalizedSources.filter((source) => source.status_label === "Connected").length;
        const optionalGapCount = normalizedSources.filter((source) => source.status_label === "Optional Gap").length;
        const optionalDisabledCount = normalizedSources.filter((source) => source.status_label === "Optional Disabled").length;
        const futureAdapterCount = normalizedSources.filter((source) => source.status_label === "Future Adapter").length;
        const providerDecisionCount = normalizedSources.filter((source) => source.status_label === "Provider Decision").length;
        const degradedCount = normalizedSources.filter((source) => source.status_label === "Degraded").length;
        const signalCount = records.filter((source) => source.eligible_for_signal_review === true).length;
        const researchCount = records.filter((source) => source.usable_for_research_context !== false).length;
        const influencingHypotheses = [...new Set(normalizedSources.flatMap((source) => asArray(source.influencing_hypotheses)))];
        const countParts = [
            `${connectedCount} connected`,
            `${degradedCount} degraded`
        ];
        if (optionalGapCount) countParts.push(`${optionalGapCount} optional gap${optionalGapCount === 1 ? "" : "s"}`);
        if (futureAdapterCount) countParts.push(`${futureAdapterCount} future adapter${futureAdapterCount === 1 ? "" : "s"}`);
        if (providerDecisionCount) countParts.push(`${providerDecisionCount} provider decision${providerDecisionCount === 1 ? "" : "s"}`);
        if (optionalDisabledCount) countParts.push(`${optionalDisabledCount} optional disabled`);
        return {
            key,
            label: pipelineLabels[key] || key.replaceAll("_", " "),
            description: pipelineDescriptions[key] || "Observation sources grouped for plain-English review.",
            source_count: records.length,
            online_count: connectedCount,
            connected_count: connectedCount,
            degraded_count: degradedCount,
            optional_gap_count: optionalGapCount,
            optional_disabled_count: optionalDisabledCount,
            future_adapter_count: futureAdapterCount,
            provider_decision_count: providerDecisionCount,
            research_usable_count: researchCount,
            signal_review_eligible_count: signalCount,
            tone: degradedCount ? "degraded" : connectedCount ? "online" : "pending",
            summary: countParts.join(", "),
            currently_influencing: influencingHypotheses[0] || "",
            influencing_hypotheses: influencingHypotheses,
            sources: normalizedSources
        };
    });
    return groups.length ? groups : asArray(sources.pipelines).map((pipeline) => ({
        key: pipeline.key || pipeline.pipeline || pipeline.label,
        label: pipeline.label || pipeline.pipeline || "Source group",
        description: pipeline.summary || "Observation sources grouped for plain-English review.",
        source_count: modelNumber(pipeline.source_count, 0),
        online_count: modelNumber(pipeline.online_count, 0),
        connected_count: modelNumber(pipeline.online_count, 0),
        degraded_count: modelNumber(pipeline.degraded_count, 0),
        optional_gap_count: modelNumber(pipeline.optional_gap_count, 0),
        research_usable_count: modelNumber(pipeline.research_usable_count, 0),
        signal_review_eligible_count: modelNumber(pipeline.signal_review_eligible_count, 0),
        tone: pipeline.tone || pipeline.status || "pending",
        summary: pipeline.summary || `${pipeline.online_count || 0}/${pipeline.source_count || 0} online.`,
        currently_influencing: "",
        influencing_hypotheses: [],
        sources: asArray(pipeline.sources).map((source) => ({
            ...source,
            status_label: source.status_label || sourceStatusLabel(source),
            status_tone: source.status_tone || statusTone(source.status_label || sourceStatusLabel(source)),
            last_update: source.last_update || source.last_heartbeat || status.generated_at || "not exported",
            description: source.description || source.role || "Observation input for Qadam's research process.",
            currently_influencing: source.currently_influencing || "",
            influencing_hypotheses: asArray(source.influencing_hypotheses),
            recent_observation: source.recent_observation || "No recent source observation exported in this snapshot."
        }))
    }));
}

function stage7PortfolioModel(status = {}, contract = {}, performance = {}) {
    const contractPortfolio = contract.portfolio || {};
    const missionPortfolio = status.mission_control?.portfolio || {};
    const capitalPortfolio = status.capital || {};
    const paperAccount = performance.paper_account || {};
    const runtimePortfolio = {
        ...paperAccount,
        ...capitalPortfolio,
        ...missionPortfolio
    };
    const orders = asArray(contractPortfolio.orders).length ? asArray(contractPortfolio.orders) : asArray(runtimePortfolio.orders);
    const openPositions = asArray(contractPortfolio.open_positions).length ? asArray(contractPortfolio.open_positions) : asArray(runtimePortfolio.open_positions);
    const closedTrades = asArray(contractPortfolio.closed_trades).length ? asArray(contractPortfolio.closed_trades) : asArray(runtimePortfolio.closed_trades);
    const equityCurve = asArray(contractPortfolio.equity_curve).length ? asArray(contractPortfolio.equity_curve) : asArray(runtimePortfolio.equity_curve);
    const targetGbp = modelNumber(contractPortfolio.target_gbp || runtimePortfolio.target_gbp, 200000);
    const baselineGbp = modelNumber(contractPortfolio.starting_balance_gbp || runtimePortfolio.starting_balance_gbp || runtimePortfolio.balance_gbp, 100000);
    const currentGbp = modelNumber(contractPortfolio.balance_gbp || contractPortfolio.current_balance_gbp || runtimePortfolio.current_balance_gbp || runtimePortfolio.equity_gbp, baselineGbp);
    const deployedGbp = paperFundDeployedValue(openPositions);
    const cashAvailableGbp = modelNumber(
        firstPresent(contractPortfolio.cash_available_gbp, contractPortfolio.cash_gbp, contractPortfolio.source_cash, runtimePortfolio.cash_available_gbp, runtimePortfolio.cash_gbp, runtimePortfolio.source_cash),
        Math.max(0, currentGbp - deployedGbp)
    );
    const capacityUsedFraction = baselineGbp ? Math.max(0, Math.min(1, deployedGbp / baselineGbp)) : 0;
    return {
        ...runtimePortfolio,
        ...contractPortfolio,
        balance_gbp: currentGbp,
        current_balance_gbp: currentGbp,
        starting_balance_gbp: baselineGbp,
        target_gbp: targetGbp,
        cash_available_gbp: cashAvailableGbp,
        deployed_gbp: deployedGbp,
        equity_curve: equityCurve,
        orders,
        closed_trades: closedTrades,
        open_positions: openPositions,
        open_position_count: modelNumber(contractPortfolio.open_position_count || runtimePortfolio.open_position_count, openPositions.length),
        order_count: modelNumber(contractPortfolio.order_count || runtimePortfolio.order_count, orders.length),
        closed_trade_count: modelNumber(contractPortfolio.closed_trade_count || runtimePortfolio.closed_trade_count, closedTrades.length),
        maturity_closed_trade_target: modelNumber(contractPortfolio.maturity_closed_trade_target || runtimePortfolio.maturity_closed_trade_target, 100),
        target_progress_fraction: targetGbp > baselineGbp ? Math.max(0, Math.min(1, (currentGbp - baselineGbp) / (targetGbp - baselineGbp))) : 0,
        capacity_used_fraction: capacityUsedFraction,
        capacity_available_gbp: Math.max(0, baselineGbp - deployedGbp),
        exposure_by_sleeve: paperFundExposureBySleeve(openPositions, baselineGbp),
        timeline_events: paperFundTimelineEvents({ ...runtimePortfolio, ...contractPortfolio, orders, open_positions: openPositions, closed_trades: closedTrades }),
        timeline_source: contractPortfolio.timeline_source || runtimePortfolio.portfolio_value_source || "paper account mirror"
    };
}

function paperFundPositionValue(position = {}) {
    const explicit = firstPresent(position.risk_size_gbp, position.market_value_gbp, position.notional_gbp, position.value_gbp);
    if (explicit !== null && explicit !== undefined && explicit !== "") return modelNumber(explicit, 0);
    const price = modelNumber(firstPresent(position.current_price, position.entry_price), 0);
    const quantity = modelNumber(firstPresent(position.quantity, position.qty, position.position_qty), 0);
    return price * quantity;
}

function paperFundDeployedValue(openPositions = []) {
    return asArray(openPositions).reduce((total, position) => total + paperFundPositionValue(position), 0);
}

function paperFundSleeveForInstrument(instrument = "") {
    const symbol = String(instrument || "").toUpperCase();
    const sleeveMap = {
        "Crude Oil": ["CL", "CL=F", "BZ", "BZ=F", "USO", "XLE", "OIH"],
        Silver: ["SI", "SI=F", "SLV", "SIL", "PAAS", "AG"],
        Semiconductors: ["SMH", "SOXX", "NVDA", "AMD", "TSM", "ASML", "AVGO", "MU"],
        "Prediction Markets": ["POLYMARKET", "ODDSPIPE", "KALSHI"],
        Defence: ["ITA", "XAR", "LMT", "RTX", "NOC", "GD", "BA", "HII"]
    };
    return Object.entries(sleeveMap).find(([_label, symbols]) => symbols.includes(symbol))?.[0] || "Other";
}

function paperFundExposureBySleeve(openPositions = [], baselineGbp = 100000) {
    const canonicalSleeves = ["Semiconductors", "Defence", "Crude Oil", "Silver", "Prediction Markets"];
    const bySleeve = new Map(canonicalSleeves.map((label) => [label, {
        label,
        deployed_gbp: 0,
        position_count: 0,
        percent_of_start: 0,
        instruments: []
    }]));
    asArray(openPositions).forEach((position) => {
        const instrument = position.instrument || position.symbol || position.asset || position.ticker || "Instrument";
        const sleeve = paperFundSleeveForInstrument(instrument);
        if (!bySleeve.has(sleeve)) {
            bySleeve.set(sleeve, { label: sleeve, deployed_gbp: 0, position_count: 0, percent_of_start: 0, instruments: [] });
        }
        const record = bySleeve.get(sleeve);
        record.deployed_gbp += paperFundPositionValue(position);
        record.position_count += 1;
        record.instruments.push(String(instrument));
    });
    return Array.from(bySleeve.values()).map((record) => ({
        ...record,
        deployed_gbp: Math.round(record.deployed_gbp * 100) / 100,
        percent_of_start: baselineGbp ? Math.round((record.deployed_gbp / baselineGbp) * 1000) / 10 : 0,
        instruments: Array.from(new Set(record.instruments))
    }));
}

function paperFundRecordId(record = {}, fallback = "record") {
    return record.trade_id || record.order_id || record.position_id || record.source_intent_id || record.intent_id || `${fallback}:${record.instrument || record.symbol || "instrument"}:${portfolioTradeTime(record) || "time"}`;
}

function paperFundLifecycleForRecord(record = {}, type = "order") {
    if (type === "position") return "Paper Position";
    if (type === "closed") return "Outcome Review";
    const direction = String(record.direction || record.side || "").toLowerCase();
    if (/sell|close|short/.test(direction)) return "Outcome Review";
    if (/buy|long/.test(direction)) return "Paper Position";
    return "Trade Candidate";
}

function paperFundTimelineEvents(portfolio = {}) {
    const events = [];
    const seen = new Set();
    const addEvent = (record, type) => {
        const id = `${type}:${paperFundRecordId(record, type)}`;
        if (seen.has(id)) return;
        seen.add(id);
        const instrument = record.instrument || record.symbol || record.asset || record.ticker || "Instrument";
        const direction = record.direction || record.side || (type === "position" ? "long" : "record");
        const timestamp = portfolioTradeTime(record);
        const pnl = modelNumber(firstPresent(record.realized_pnl_gbp, record.unrealized_pnl_gbp), 0);
        events.push({
            id,
            type,
            instrument,
            direction,
            timestamp,
            status: record.status || record.order_status || record.postmortem_status || (type === "position" ? "open position" : "recorded"),
            pnl_gbp: pnl,
            tone: pnl > 0 ? "online" : (pnl < 0 ? "blocked" : statusClass(record.status || "pending")),
            lifecycle: paperFundLifecycleForRecord(record, type),
            record
        });
    };
    asArray(portfolio.orders).forEach((record) => addEvent(record, "order"));
    asArray(portfolio.open_positions).forEach((record) => addEvent(record, "position"));
    asArray(portfolio.closed_trades).forEach((record) => addEvent(record, "closed"));
    return events
        .filter((event) => event.timestamp || event.type === "position")
        .sort((a, b) => (Date.parse(b.timestamp || "") || 0) - (Date.parse(a.timestamp || "") || 0))
        .slice(0, 80);
}

function stage7SleeveDisplayLabel(value) {
    const token = String(value || "").toLowerCase().replaceAll("_", " ").trim();
    if (token === "oil" || token === "crude oil") return "Crude Oil";
    if (token === "defence stocks" || token === "defense stocks" || token === "defense") return "Defence";
    if (token === "prediction markets" || token === "prediction market") return "Prediction Markets";
    if (token === "semiconductors") return "Semiconductors";
    if (token === "silver") return "Silver";
    return dashboardText(value, "Market sleeve");
}

function stage7SleeveKey(value) {
    return String(stage7SleeveDisplayLabel(value))
        .toLowerCase()
        .replace(/&/g, "and")
        .replace(/[^a-z0-9]+/g, "_")
        .replace(/^_+|_+$/g, "");
}

function stage7StrategyInstrumentKey(value) {
    const token = String(value || "").toLowerCase().replaceAll(" ", "_");
    if (token === "oil") return "crude_oil";
    if (token === "defense") return "defence";
    return token;
}

function stage7MarketCurrentState(sleeve = {}, family = {}, activePatterns = [], heldPositions = []) {
    if (heldPositions.length) return "Holding";
    const state = String(sleeve.status || family.current_state || "").toLowerCase();
    if (/ignore|disabled|out_of_scope/.test(state)) return "Ignoring";
    if (activePatterns.length || family.visible_in_cockpit || state) return "Watching";
    return "Ignoring";
}

function stage7MarketAkberGate(state, family = {}, activePatterns = []) {
    const familyState = String(family.current_state || family.setup_state || "").toLowerCase();
    if (state === "Holding") return "Execution";
    if (/qualified|paper_review|production/.test(familyState)) return "Risk";
    if (/risk|sizing|staged/.test(familyState)) return "Risk";
    if (activePatterns.length) return "Confirmation";
    return "Context";
}

function stage7MarketMovement(sleeve = {}, heldPositions = [], activePatterns = []) {
    const pnl = heldPositions.reduce((total, position) => total + modelNumber(position.unrealized_pnl_gbp || position.realized_pnl_gbp, 0), 0);
    if (heldPositions.length) {
        const direction = pnl > 0 ? "up" : (pnl < 0 ? "down" : "flat");
        return {
            direction,
            reason: `${heldPositions.map((position) => position.instrument || position.symbol).filter(Boolean).join(", ")} paper holding is ${direction} by ${formatMoney(pnl)} in the mirrored Alpaca Paper account.`
        };
    }
    const pattern = activePatterns[0] || {};
    const confidenceDelta = modelNumber(pattern.confidence_after_quantum_review, 0) - modelNumber(pattern.confidence_before_quantum_review, 0);
    if (confidenceDelta > 0) {
        return {
            direction: "up",
            reason: `Pattern confidence improved after quantum review, but Qadam is still waiting for persistence and confirmation.`
        };
    }
    if (confidenceDelta < 0) {
        return {
            direction: "down",
            reason: `Pattern confidence weakened after review, so Qadam is keeping this sleeve under watch only.`
        };
    }
    return {
        direction: "flat",
        reason: dashboardText(pattern.observed_relationship || sleeve.pattern_question, "No recent price movement reason exported; Qadam is watching for source-price divergence.")
    };
}

function stage7MarketSleeves(edge = {}, strategy = {}, context = {}) {
    const fallbackSymbols = {
        "Crude Oil": ["CL=F", "BZ=F", "USO", "XLE"],
        Silver: ["SI=F", "SLV", "SIL", "PAAS"],
        Semiconductors: ["SMH", "SOXX", "NVDA", "AMD", "TSM", "ASML"],
        "Prediction Markets": ["Polymarket CLOB", "OddsPipe spreads", "Kalshi events"],
        Defence: ["ITA", "XAR", "LMT", "RTX", "NOC"]
    };
    const sleeves = asArray(edge.sleeves).length
        ? asArray(edge.sleeves)
        : Object.entries(fallbackSymbols).map(([label, symbols]) => ({
            key: label.toLowerCase().replaceAll(" ", "_"),
            label,
            watched_instruments: symbols.map((symbol) => ({ symbol, label: symbol, paper_route: "watchlist" })),
            pattern_question: "Waiting for the source-price scan to export a pattern question.",
            strategy_use: "Market sleeve under Qadam review.",
            status: "pending"
        }));
    const familiesByInstrument = new Map(asArray(strategy.strategy_families || strategy.families).map((family) => [
        stage7StrategyInstrumentKey(family.instrument || family.key),
        family
    ]));
    const openPositions = asArray(context.paper?.open_positions);
    const activePatterns = asArray(context.candidate_patterns);
    const sourceLedger = asArray(context.status?.watching).length
        ? asArray(context.status.watching)
        : asArray(context.status?.mission_control?.data_sources?.ledger);
    const sourceNameByKey = new Map(sourceLedger.map((source) => [
        source.source_key || source.key,
        dashboardText(source.source_name || source.name || source.source_key || source.key, "Source")
    ]));
    const order = ["crude_oil", "silver", "semiconductors", "prediction_markets", "defence"];
    return sleeves.map((sleeve) => {
        const rawLabel = sleeve.label || sleeve.key || "Market sleeve";
        const label = stage7SleeveDisplayLabel(rawLabel);
        const key = stage7SleeveKey(label);
        const family = familiesByInstrument.get(stage7StrategyInstrumentKey(sleeve.key))
            || familiesByInstrument.get(stage7StrategyInstrumentKey(label))
            || {};
        const sleevePatterns = activePatterns.filter((pattern) => (
            stage7SleeveKey(pattern.sleeve_key || pattern.market_sleeve || pattern.label) === key
            || stage7StrategyInstrumentKey(pattern.sleeve_key) === stage7StrategyInstrumentKey(sleeve.key)
        ));
        const instruments = asArray(sleeve.watched_instruments);
        const instrumentSymbols = new Set(instruments.map((instrument) => String(instrument.symbol || instrument.label || "").toUpperCase()));
        const heldPositions = openPositions.filter((position) => {
            const instrument = String(position.instrument || position.symbol || "").toUpperCase();
            return instrumentSymbols.has(instrument) || stage7SleeveDisplayLabel(paperFundSleeveForInstrument(instrument)) === label;
        });
        const currentState = stage7MarketCurrentState(sleeve, family, sleevePatterns, heldPositions);
        const movement = stage7MarketMovement(sleeve, heldPositions, sleevePatterns);
        const akberGate = stage7MarketAkberGate(currentState, family, sleevePatterns);
        const sourceKeys = asArray(sleeve.primary_lens_source_keys).length
            ? asArray(sleeve.primary_lens_source_keys)
            : asArray(sleeve.source_keys).slice(0, 10);
        const sourceLabels = sourceKeys.map((sourceKey) => sourceNameByKey.get(sourceKey) || dashboardText(sourceKey)).slice(0, 12);
        const instrumentSummary = instruments.map((instrument) => instrument.symbol || instrument.label).filter(Boolean).slice(0, 6).join(", ");
        return {
            key,
            label,
            raw_status: sleeve.status || family.current_state || "watching",
            current_state: currentState,
            status: currentState,
            tone: currentState === "Holding" ? "online" : (currentState === "Watching" ? "pending" : "degraded"),
            watched_instruments: instruments.map((instrument) => ({
                symbol: instrument.symbol || instrument.label || "Instrument",
                label: instrument.label || instrument.symbol || "Instrument",
                instrument_type: instrument.instrument_type || "watchlist item",
                paper_route: instrument.paper_route || "watchlist context",
                status_note: heldPositions.some((position) => String(position.instrument || position.symbol || "").toUpperCase() === String(instrument.symbol || instrument.label || "").toUpperCase())
                    ? "Currently held in Alpaca Paper"
                    : dashboardText(instrument.paper_route || instrument.instrument_type, "Watched for market confirmation")
            })),
            instrument_summary: instrumentSummary || "No instruments exported",
            pattern_question: sleeve.pattern_question || "No pattern question exported.",
            strategy_use: sleeve.strategy_use || family.qadam_fit_reason || "Strategy use not exported.",
            active_strategy: family.label || family.key || "Strategy match pending",
            strategy_fit: family.fit || "not scored",
            strategy_fit_score: firstPresent(family.fit_score, null),
            strategy_rank: firstPresent(family.rank, null),
            why_this_market_matters: sleeve.pattern_question || family.qadam_fit_reason || "Qadam watches this sleeve for source-price divergence and paper-tradable edge.",
            active_hypothesis_count: sleevePatterns.length,
            active_hypotheses: sleevePatterns.map((pattern) => ({
                id: pattern.pattern_id || pattern.sleeve_key || key,
                label: dashboardText(pattern.market_sleeve || label),
                status: dashboardText(pattern.status || "under review"),
                summary: dashboardText(pattern.observed_relationship || pattern.lead_lag_or_divergence_hypothesis || "Pattern review is active."),
                missing: asArray(pattern.missing_criteria).map((item) => dashboardText(item))
            })),
            recent_movement_direction: movement.direction,
            recent_movement_reason: movement.reason,
            akber_gate: akberGate,
            held_instruments: heldPositions.map((position) => position.instrument || position.symbol).filter(Boolean),
            source_keys: sourceKeys,
            source_labels: sourceLabels,
            source_connection_summary: `${modelNumber(sleeve.online_source_count, 0)}/${modelNumber(sleeve.source_count, 37)} sources connected; ${modelNumber(sleeve.signal_review_eligible_source_count, 0)} can support signal review.`,
            online_source_count: modelNumber(sleeve.online_source_count, 0),
            signal_review_eligible_source_count: modelNumber(sleeve.signal_review_eligible_source_count, 0),
            order_index: order.includes(key) ? order.indexOf(key) : 99
        };
    }).sort((a, b) => a.order_index - b.order_index);
}

function stage7AkberStageLabels(akberLens = {}) {
    const fallback = ["Context", "Catalyst", "Confirmation", "Risk", "Execution", "Postmortem Learning"];
    const stages = asArray(akberLens.stages).length ? asArray(akberLens.stages) : fallback;
    const normalized = stages.map((stage) => {
        const text = dashboardText(stage, "");
        if (!text) return "";
        if (/postmortem/i.test(text)) return "Postmortem Learning";
        return text.split(/[\s_-]+/).filter(Boolean).map((part) => (
            part.length <= 3 && part === part.toUpperCase()
                ? part
                : part.charAt(0).toUpperCase() + part.slice(1).toLowerCase()
        )).join(" ");
    }).filter(Boolean);
    return normalized.length ? normalized.slice(0, 6) : fallback;
}

function stage7StrategySleeveKey(family = {}) {
    return stage7StrategyInstrumentKey(family.instrument || family.sleeve || family.market_sleeve || family.key);
}

function stage7StrategyPatternForFamily(family = {}, patterns = []) {
    const familyKey = stage7StrategySleeveKey(family);
    return asArray(patterns).find((pattern) => (
        stage7StrategyInstrumentKey(pattern.sleeve_key || pattern.market_sleeve || pattern.label) === familyKey
        || stage7SleeveKey(pattern.market_sleeve || pattern.label || pattern.sleeve_key) === stage7SleeveKey(family.instrument || family.sleeve || family.label)
    )) || {};
}

function stage7StrategySleeveForFamily(family = {}, marketSleeves = []) {
    const familyKey = stage7StrategySleeveKey(family);
    return asArray(marketSleeves).find((sleeve) => (
        stage7StrategyInstrumentKey(sleeve.key || sleeve.label) === familyKey
        || stage7SleeveKey(sleeve.label || sleeve.key) === stage7SleeveKey(family.instrument || family.sleeve || family.label)
    )) || {};
}

function stage7StrategyLifecycle(family = {}, sleeve = {}, pattern = {}) {
    const reason = String(family.current_reason || family.setup_state || family.current_state || "").toLowerCase();
    const held = asArray(sleeve.held_instruments).length > 0 || sleeve.current_state === "Holding";
    if (held) {
        return {
            status: "In paper position",
            tone: "online",
            gate: "Execution",
            last_gate_passed: "Risk",
            next_gate_needed: "Postmortem Learning",
            why_not_ready: "This strategy already has mirrored Alpaca Paper exposure; Qadam is watching outcome, risk, and postmortem learning next."
        };
    }
    if (family.qualified_setup) {
        return {
            status: "Ready for paper review",
            tone: "online",
            gate: "Risk",
            last_gate_passed: "Confirmation",
            next_gate_needed: "Execution",
            why_not_ready: "The setup has reached guarded paper review; it still needs the PaperOps execution route and idempotency gates before a new paper order."
        };
    }
    if (/risk|sizing|notional|paper staging|paper_order|venue|execution|route/.test(reason)) {
        return {
            status: "Under risk review",
            tone: "pending",
            gate: "Risk",
            last_gate_passed: "Confirmation",
            next_gate_needed: "Execution",
            why_not_ready: dashboardText(family.current_reason, "Waiting for risk sizing, route readiness, and paper staging confirmation.")
        };
    }
    if (pattern.status || /confirm|corroborat|signal/.test(reason)) {
        return {
            status: "Waiting for confirmation",
            tone: "pending",
            gate: "Confirmation",
            last_gate_passed: "Catalyst",
            next_gate_needed: "Risk",
            why_not_ready: dashboardText(family.current_reason, "Waiting for price confirmation against the source signal.")
        };
    }
    if (family.catalyst_focus) {
        return {
            status: "Catalyst detected",
            tone: "pending",
            gate: "Catalyst",
            last_gate_passed: "Context",
            next_gate_needed: "Confirmation",
            why_not_ready: "Qadam has a catalyst theme, but it still needs source agreement and market confirmation."
        };
    }
    return {
        status: "Watching for context",
        tone: "degraded",
        gate: "Context",
        last_gate_passed: "None",
        next_gate_needed: "Catalyst",
        why_not_ready: "Qadam is still collecting enough context before treating this as a catalyst."
    };
}

function stage7StrategyTrend(family = {}, sleeve = {}, pattern = {}) {
    const delta = modelNumber(pattern.confidence_after_quantum_review, 0) - modelNumber(pattern.confidence_before_quantum_review, 0);
    if (delta > 0.02) {
        return {
            direction: "More relevant",
            tone: "online",
            reason: "Quantum review increased this sleeve's pattern confidence over the latest daily edge pass."
        };
    }
    if (delta < -0.02) {
        return {
            direction: "Less relevant",
            tone: "blocked",
            reason: "The latest review reduced this sleeve's confidence, so Qadam is deprioritising it."
        };
    }
    if (sleeve.current_state === "Holding" || family.qualified_setup) {
        return {
            direction: "More relevant",
            tone: "online",
            reason: "The strategy is either in a mirrored paper position or has reached guarded paper review."
        };
    }
    return {
        direction: "Stable",
        tone: "pending",
        reason: "No decisive 24-hour confidence shift is exported; Qadam is keeping it under watch."
    };
}

function stage7StrategyGateBreakdown(stageLabels = [], lifecycle = {}) {
    const labels = stageLabels.length ? stageLabels : stage7AkberStageLabels();
    const gateIndex = Math.max(0, labels.findIndex((label) => label.toLowerCase() === String(lifecycle.gate || "").toLowerCase()));
    return labels.map((label, index) => {
        const state = index < gateIndex ? "passed" : (index === gateIndex ? "active" : "pending");
        return {
            label,
            state,
            explanation: state === "passed"
                ? `${label} has already passed for this strategy.`
                : (state === "active" ? `${label} is the current Akber gate.` : `${label} is still pending.`)
        };
    });
}

function stage7StrategyPlaybookFamilies(strategy = {}, marketSleeves = [], paper = {}, patterns = []) {
    const stageLabels = stage7AkberStageLabels(strategy.akber_lens);
    return asArray(strategy.strategy_families || strategy.families).slice(0, 5).map((family) => {
        const sleeve = stage7StrategySleeveForFamily(family, marketSleeves);
        const pattern = stage7StrategyPatternForFamily(family, patterns);
        const lifecycle = stage7StrategyLifecycle(family, sleeve, pattern);
        const trend = stage7StrategyTrend(family, sleeve, pattern);
        const gateBreakdown = stage7StrategyGateBreakdown(stageLabels, lifecycle);
        const sourceFamilies = asArray(pattern.source_families_involved).map((source) => dashboardText(source, "Source family"));
        return {
            ...family,
            label: family.label || family.key || "Strategy family",
            market_sleeve: sleeve.label || stage7SleeveDisplayLabel(family.instrument || family.key),
            sleeve_key: sleeve.key || stage7SleeveKey(family.instrument || family.key),
            lifecycle_status: lifecycle.status,
            lifecycle_tone: lifecycle.tone,
            current_akber_gate: lifecycle.gate,
            last_gate_passed: lifecycle.last_gate_passed,
            next_gate_needed: lifecycle.next_gate_needed,
            why_not_ready: lifecycle.why_not_ready,
            trend_direction: trend.direction,
            trend_tone: trend.tone,
            trend_reason: trend.reason,
            gate_breakdown: gateBreakdown,
            evidence_summary: dashboardText(pattern.observed_relationship || family.current_reason || family.qadam_fit_reason, "No current evidence summary exported for this strategy."),
            linked_hypothesis: dashboardText(pattern.lead_lag_or_divergence_hypothesis || pattern.trading_strategy_implication || family.catalyst_focus, "No linked hypothesis exported yet."),
            source_families: sourceFamilies,
            active_hypothesis_count: modelNumber(sleeve.active_hypothesis_count, pattern.status ? 1 : 0),
            held_instruments: asArray(sleeve.held_instruments),
            paper_notional_gbp: modelNumber(family.notional_gbp, 0),
            display_rank: firstPresent(family.rank, "n/a"),
            display_fit_score: firstPresent(family.fit_score, family.fit, "n/a")
        };
    });
}

function stage7Percent(value, fallback = 0) {
    const number = modelNumber(value, fallback);
    return `${Math.round(Math.max(0, Math.min(1, number)) * 100)}%`;
}

function stage7TitleFromKey(value = "") {
    return String(value || "")
        .replaceAll("_", " ")
        .replace(/\s+/g, " ")
        .trim()
        .split(" ")
        .map((word) => word ? word.charAt(0).toUpperCase() + word.slice(1).toLowerCase() : "")
        .join(" ");
}

function stage7HypothesisLifecycleStage(pattern = {}, lifecycle = {}) {
    const text = [
        pattern.status,
        pattern.edge_stage,
        lifecycle.lifecycle_state,
        lifecycle.decision,
        lifecycle.strategy_update_status
    ].join(" ").toLowerCase();
    if (/paper position|open position|position/.test(text) || pattern.paper_order_allowed) return "Paper position";
    if (/outcome|postmortem|closed/.test(text)) return "Outcome review";
    if (/strategy learning|strategy_update/.test(text)) return "Strategy learning";
    if (/trade candidate|signal_integrity|candidate_promotion/.test(text) && pattern.trade_candidate_creation_allowed) return "Trade candidate";
    if (/testing|backtest|replay/.test(text)) return "Testing";
    if (/under review|held|candidate|observed|corroboration|not approved|not_validated/.test(text)) return "Hypothesis under review";
    if (/detected|pattern/.test(text)) return "Pattern detected";
    return "Watching";
}

function stage7HypothesisMetric(label, valueLabel, detail, tone = "pending") {
    return {
        label,
        value_label: dashboardText(valueLabel, "not exported"),
        detail: dashboardText(detail, "No detail exported."),
        tone
    };
}

function stage7HypothesisMetricSet(pattern = {}, enginePattern = {}) {
    const passedCriteria = asArray(pattern.passed_criteria || enginePattern.passed_criteria);
    const missingCriteria = asArray(pattern.missing_criteria || enginePattern.missing_criteria);
    const criterionTotal = passedCriteria.length + missingCriteria.length;
    const evidenceScore = modelNumber(
        firstPresent(pattern.confidence_after_quantum_review, enginePattern.edge_readiness_score, enginePattern.criterion_score),
        0
    );
    const sourceScore = modelNumber(firstPresent(enginePattern.primary_lens_overlap_score, enginePattern.source_pressure_score), 0);
    const marketScore = modelNumber(firstPresent(enginePattern.signal_review_coverage_score, passedCriteria.includes("market_confirmation") ? 0.72 : 0.38), 0);
    const readinessLabel = criterionTotal
        ? `${passedCriteria.length}/${criterionTotal} criteria`
        : (pattern.trade_candidate_creation_allowed ? "Candidate-ready" : "Criteria pending");
    const readinessTone = pattern.trade_candidate_creation_allowed || pattern.paper_order_allowed
        ? "online"
        : (missingCriteria.length ? "pending" : "degraded");
    return [
        stage7HypothesisMetric(
            "Evidence Strength",
            stage7Percent(evidenceScore),
            `Confidence after review is ${stage7Percent(evidenceScore)}${pattern.confidence_before_quantum_review ? `, versus ${stage7Percent(pattern.confidence_before_quantum_review)} before quantum review` : ""}.`,
            evidenceScore >= 0.7 ? "online" : "pending"
        ),
        stage7HypothesisMetric(
            "Source Agreement",
            `${asArray(pattern.source_families_involved || enginePattern.primary_lens_source_keys).length || pattern.source_count || enginePattern.source_count || 0} feeds`,
            `Qadam is comparing this sleeve against the source universe, not a single feed. Source overlap score is ${stage7Percent(sourceScore)}.`,
            sourceScore >= 0.65 || asArray(pattern.source_families_involved).length >= 5 ? "online" : "pending"
        ),
        stage7HypothesisMetric(
            "Market Reaction",
            stage7Percent(marketScore),
            passedCriteria.includes("market_confirmation")
                ? "Market confirmation is present, but still not enough by itself to approve a trade."
                : "Market reaction has not confirmed the source pattern strongly enough yet.",
            marketScore >= 0.65 ? "online" : "pending"
        ),
        stage7HypothesisMetric(
            "Trade Readiness",
            readinessLabel,
            missingCriteria.length
                ? `Still waiting for ${missingCriteria.map(stage7TitleFromKey).join(", ")}.`
                : "Downstream risk, PaperOps, idempotency, and Alpaca Paper gates still decide whether anything can be submitted.",
            readinessTone
        )
    ];
}

function stage7HypothesisWhyNoTrade(pattern = {}, lifecycle = {}, metrics = []) {
    const missing = asArray(pattern.missing_criteria || lifecycle.missing_correlations);
    if (pattern.paper_order_allowed || pattern.trade_candidate_creation_allowed) {
        return "This has not become a new paper order yet because PaperOps, idempotency, risk sizing, and Alpaca Paper route checks still have to accept a fresh eligible setup.";
    }
    if (lifecycle.decision_reason) {
        return dashboardText(lifecycle.decision_reason);
    }
    if (missing.length) {
        return `No trade yet because Qadam is still waiting for ${missing.map(stage7TitleFromKey).join(", ")} before this can move past hypothesis review.`;
    }
    const readiness = asArray(metrics).find((metric) => metric.label === "Trade Readiness");
    return `No trade yet because this remains research evidence: ${dashboardText(readiness?.detail, "risk and paper-route gates have not accepted it.")}`;
}

function stage7HypothesisSourceMeta(sourceKeys = [], sourceGroups = []) {
    const sourceMap = new Map();
    asArray(sourceGroups).forEach((group) => {
        asArray(group.sources).forEach((source) => {
            sourceMap.set(source.key, {
                key: source.key,
                name: source.name,
                category: group.label,
                status_label: source.status_label,
                status_tone: source.status_tone,
                description: source.description
            });
        });
    });
    return asArray(sourceKeys).map((sourceKey) => (
        sourceMap.get(sourceKey) || {
            key: sourceKey,
            name: stage7TitleFromKey(sourceKey),
            category: "Source category",
            status_label: "Connected",
            status_tone: "pending",
            description: "Source participates in the all-source pattern scan for this sleeve."
        }
    ));
}

function stage7FindLifecycleForPattern(pattern = {}, lifecycle = {}) {
    const threads = asArray(lifecycle.hypothesis_threads);
    const patternSleeve = stage7SleeveKey(pattern.market_sleeve || pattern.label || pattern.sleeve_key);
    return threads.find((thread) => (
        stage7SleeveKey(thread.market_sleeve || thread.sleeve_key || thread.instrument_focus) === patternSleeve
    )) || {};
}

function stage7HypothesisCards(patterns = [], context = {}) {
    const enginePatterns = asArray(context.pattern_engine?.candidate_patterns);
    const engineById = new Map(enginePatterns.map((pattern) => [pattern.pattern_id, pattern]));
    const engineBySleeve = new Map(enginePatterns.map((pattern) => [stage7SleeveKey(pattern.market_sleeve || pattern.sleeve_key), pattern]));
    const strategiesBySleeve = new Map(asArray(context.strategy_families).map((family) => [stage7SleeveKey(family.market_sleeve || family.sleeve_key || family.label), family]));
    const quantMethodLabel = context.quant_method_label || "Classical Fallback (Deterministic)";
    return asArray(patterns).map((pattern) => {
        const sleeveLabel = stage7SleeveDisplayLabel(pattern.market_sleeve || pattern.label || pattern.sleeve_key || "Market sleeve");
        const sleeveKey = stage7SleeveKey(sleeveLabel);
        const enginePattern = engineById.get(pattern.pattern_id) || engineBySleeve.get(sleeveKey) || {};
        const lifecycle = stage7FindLifecycleForPattern(pattern, context.hypothesis_lifecycle);
        const strategy = strategiesBySleeve.get(sleeveKey) || {};
        const lifecycleStage = stage7HypothesisLifecycleStage(pattern, lifecycle);
        const metrics = stage7HypothesisMetricSet(pattern, enginePattern);
        const sourceKeys = asArray(pattern.source_families_involved || enginePattern.primary_lens_source_keys || pattern.source_keys).slice(0, 14);
        const triggeredSources = stage7HypothesisSourceMeta(sourceKeys, context.source_groups);
        const sourceCategories = [...new Set(triggeredSources.map((source) => source.category))];
        const whyNoTradeYet = stage7HypothesisWhyNoTrade(pattern, lifecycle, metrics);
        const missingCriteria = asArray(pattern.missing_criteria || enginePattern.missing_criteria || lifecycle.missing_correlations);
        const passedCriteria = asArray(pattern.passed_criteria || enginePattern.passed_criteria);
        return {
            id: pattern.pattern_id || lifecycle.lifecycle_id || sleeveKey,
            sleeve_key: sleeveKey,
            market_sleeve: sleeveLabel,
            lifecycle_stage: lifecycleStage,
            lifecycle_tone: lifecycleStage === "Trade candidate" || lifecycleStage === "Paper position" ? "online" : "pending",
            pattern_summary: dashboardText(pattern.observed_relationship || enginePattern.pattern_question || lifecycle.representative_thesis, "Qadam is testing whether source movement repeatedly explains this watched market."),
            plain_english_pattern: dashboardText(pattern.lead_lag_or_divergence_hypothesis || lifecycle.representative_thesis || pattern.trading_strategy_implication, "Qadam is looking for source-price divergence that repeats over time."),
            why_no_trade_yet: whyNoTradeYet,
            full_why_no_trade_yet: `${whyNoTradeYet} This dashboard can explain the hypothesis, but it cannot create trade authority.`,
            metrics,
            triggered_sources: triggeredSources,
            triggered_source_count: triggeredSources.length,
            source_categories: sourceCategories,
            source_category_label: sourceCategories.length ? sourceCategories.slice(0, 3).join(" + ") : "Source category not mapped",
            market_symbols: asArray(pattern.watched_market_symbols || enginePattern.instrument_symbols || pattern.instrument_symbols),
            strategy_evaluating: strategy.label || enginePattern.strategy_use || pattern.trading_strategy_implication || "Strategy match pending",
            strategy_gate: strategy.current_akber_gate || "Confirmation",
            llm_agreement_status: dashboardText(context.llm_review?.status || pattern.llm_role || "LLM review active"),
            llm_agreement_detail: dashboardText(pattern.llm_role || context.llm_review?.role, "Local LLM compresses the source context and frontier LLM challenges the explanation."),
            quantum_review_status: dashboardText(pattern.quantum_non_linear_review_result?.status || context.quantum_review?.status || context.quantum_gate?.status || "not exported"),
            quantum_review_method: quantMethodLabel,
            quantum_review_detail: dashboardText(pattern.quantum_non_linear_review_result?.finding || context.quantum_review?.role || context.daily_edge?.non_linear_pattern_summary, "Quantum review is a mandatory non-linear challenge before Qadam may call a pattern an edge."),
            confirmation_needed: missingCriteria.length
                ? `Confirmation needed: ${missingCriteria.map(stage7TitleFromKey).join(", ")}.`
                : "Confirmation needed: fresh signal integrity, risk sizing, idempotency, and PaperOps acceptance.",
            invalidation_rule: dashboardText(lifecycle.invalidation, "Invalidate this if source agreement fades, the market reaction contradicts the thesis, or the pattern stops repeating."),
            flow: [
                { label: "Source Category", value: sourceCategories[0] || "All-source scan", detail: sourceCategories.slice(1).join(", ") || "All available Qadam source groups are scanned." },
                { label: "Market Sleeve", value: sleeveLabel, detail: asArray(pattern.watched_market_symbols || enginePattern.instrument_symbols).slice(0, 5).join(", ") || "Watched instruments not exported." },
                { label: "Strategy Evaluating", value: strategy.label || "Strategy match pending", detail: strategy.current_akber_gate ? `Current Akber gate: ${strategy.current_akber_gate}` : "Strategy gate pending." },
                { label: "Hypothesis Stage", value: lifecycleStage, detail: whyNoTradeYet }
            ],
            passed_criteria: passedCriteria.map(stage7TitleFromKey),
            missing_criteria: missingCriteria.map(stage7TitleFromKey),
            boundary: "Hypotheses can inform ranking and review only. They cannot approve risk, submit paper orders, write brokers, or enable live capital."
        };
    });
}

const STAGE7_LEARNING_METHOD_LABELS = [
    "True Backtest",
    "Scenario Replay",
    "Paper Forward",
    "Postmortem"
];

function stage7LearningProposalStatus(record = {}) {
    const text = String([
        record.status,
        record.decision_status,
        record.proposal_status,
        record.promotion_gate_passed ? "approved" : "",
        record.promotion_allowed ? "approved" : "",
        record.applied ? "approved" : "",
        record.rejected ? "rejected" : ""
    ].join(" ")).toLowerCase();
    if (/approved|applied|passed/.test(text) && !/not applied|not_applied|held|blocked/.test(text)) return "Approved";
    if (/reject|refut|discard|failed/.test(text)) return "Rejected";
    return "Pending Human Review";
}

function stage7LearningProposalTone(status) {
    if (status === "Approved") return "online";
    if (status === "Rejected") return "blocked";
    return "pending";
}

function stage7LearningRecordsBySleeve(records = []) {
    return asArray(records).reduce((acc, record) => {
        const key = stage7SleeveKey(record.market_sleeve || record.sleeve_key || record.instrument_key || record.strategy_family_name || record.strategy_family_key);
        if (key && !acc.has(key)) acc.set(key, record);
        return acc;
    }, new Map());
}

function stage7LearningProposalRecord(record = {}, fallback = {}) {
    const sleeve = stage7SleeveDisplayLabel(record.market_sleeve || record.sleeve_key || record.instrument_key || fallback.market_sleeve || "Market sleeve");
    const status = stage7LearningProposalStatus(record);
    return {
        id: record.update_id || record.weight_update_id || record.promotion_gate_id || record.source_proposal_id || fallback.id || stage7SleeveKey(sleeve),
        sleeve,
        status,
        status_tone: stage7LearningProposalTone(status),
        proposal: dashboardText(
            record.proposed_adjustment
                || record.strategy_update_proposed_adjustment
                || record.recommendation
                || record.source_proposal_kind
                || fallback.proposal,
            "Keep observing before changing strategy priority."
        ),
        would_change: dashboardText(
            record.target_strategy_component
                || record.target_weight_surface
                || record.strategy_family_name
                || fallback.would_change,
            "Strategy research priority only."
        ),
        reason: dashboardText(record.reason || record.rationale || record.allowed_next_action || fallback.reason, "Proposal is recorded for review and is not applied automatically."),
        rollback_condition: dashboardText(record.rollback_condition || fallback.rollback_condition, "Rollback or discard if the evidence weakens, contradicts later paper outcomes, or fails review."),
        boundary: dashboardText(record.blocked_action || fallback.boundary, "Human-governed proposal only. No strategy mutation, paper order, broker write, or live-capital change is created here.")
    };
}

function stage7LearningDefinitions() {
    return [
        {
            label: "True Backtest",
            summary: "A historical simulation of a strategy against prior market and source data."
        },
        {
            label: "Scenario Replay",
            summary: "A past or current setup rerun through Qadam's current logic to see how it would classify the evidence."
        },
        {
            label: "Paper Forward",
            summary: "The live paper-trading record: what Qadam actually held, submitted, closed, or avoided."
        },
        {
            label: "Postmortem",
            summary: "The learning review after a closed paper trade or rejected setup."
        }
    ];
}

function stage7LearningLoopModel(status = {}, edge = {}) {
    const daily = status.daily_edge_findings_brief || {};
    const patternEngine = status.pattern_recognition_engine || {};
    const memory = status.edge_memory_ledger || {};
    const lifecycle = status.hypothesis_lifecycle || {};
    const updates = status.strategy_update_record || {};
    const weights = status.strategy_weight_updates || {};
    const meta = status.quantum_meta_review || {};
    const promotion = status.promotion_gates || {};
    const formalBacktest = status.backtest_results || status.backtesting_results || status.backtesting || null;
    const patterns = asArray(daily.patterns_observed).length
        ? asArray(daily.patterns_observed)
        : asArray(edge.pattern_ledger?.patterns || patternEngine.candidate_patterns);
    const updatesBySleeve = stage7LearningRecordsBySleeve(updates.proposals || daily.strategy_updates);
    const weightsBySleeve = stage7LearningRecordsBySleeve(weights.weight_update_records);
    const metaBySleeve = stage7LearningRecordsBySleeve(meta.meta_review_records);
    const promotionBySleeve = stage7LearningRecordsBySleeve(promotion.promotion_gate_decisions);
    const proposalQueue = (
        asArray(updates.proposals).length
            ? asArray(updates.proposals)
            : (asArray(weights.weight_update_records).length ? asArray(weights.weight_update_records) : asArray(daily.strategy_updates))
    ).slice(0, 6).map((record) => stage7LearningProposalRecord(record));
    const paperClosedTrades = asArray(status.capital?.closed_trades || status.paper_fund_status?.closed_trades);
    const paperOpenPositions = asArray(status.capital?.open_positions || status.paper_fund_status?.open_positions);
    const replayItems = patterns.slice(0, 5).map((pattern) => {
        const sleeve = stage7SleeveDisplayLabel(pattern.market_sleeve || pattern.sleeve_key || "Market sleeve");
        const sleeveKey = stage7SleeveKey(sleeve);
        const update = updatesBySleeve.get(sleeveKey) || {};
        const weight = weightsBySleeve.get(sleeveKey) || {};
        const metaReview = metaBySleeve.get(sleeveKey) || {};
        const promotionGate = promotionBySleeve.get(sleeveKey) || {};
        const proposal = stage7LearningProposalRecord(weight.strategy_family_name ? weight : (update.update_id ? update : promotionGate), {
            market_sleeve: sleeve,
            proposal: pattern.trading_strategy_implication,
            would_change: "Research priority for this market sleeve.",
            reason: pattern.lead_lag_or_divergence_hypothesis,
            boundary: "Research and replay output only. Downstream Strategy Lead, Signal Integrity, Risk, PaperOps, and Alpaca Paper gates remain separate."
        });
        const missingCriteria = asArray(pattern.missing_criteria);
        const passedCriteria = asArray(pattern.passed_criteria);
        const confidence = modelNumber(pattern.confidence_after_quantum_review, modelNumber(weight.latest_edge_readiness_score, 0));
        return {
            id: pattern.pattern_id || `replay-${sleeveKey}`,
            method_label: "Scenario Replay",
            status_tone: "pending",
            title: `${sleeve} replay`,
            hypothesis: dashboardText(pattern.observed_relationship, `${sleeve} is being tested for repeatable source-price behaviour.`),
            method: "Replay only - no historical simulation available yet.",
            market_sleeve: sleeve,
            data_used: `${modelNumber(pattern.source_count, 0)} sources, ${asArray(pattern.watched_market_symbols).slice(0, 6).join(", ") || "watched instruments"}, quantum-reviewed pattern artifact.`,
            result_so_far: `Replay only - no historical simulation available yet. Current review has ${passedCriteria.length} passed criteria, ${missingCriteria.length || 0} missing criteria, and ${stage7Percent(confidence)} reviewed confidence.`,
            proposal: proposal.proposal,
            proposal_status: proposal.status,
            proposal_status_tone: proposal.status_tone,
            proposal_reason: proposal.reason,
            strategy_feedback_proposal: proposal,
            quantum_review: dashboardText(pattern.quantum_non_linear_review_result?.status || metaReview.quantum_review_status || meta.status, "not exported"),
            what_would_confirm: missingCriteria.length
                ? `Needs ${missingCriteria.map(stage7TitleFromKey).join(", ")}.`
                : "Needs fresh Signal Integrity, Risk, PaperOps, and paper-route acceptance.",
            what_would_invalidate: dashboardText(weight.rollback_condition || update.rollback_condition, "Invalidate if the relationship decays, reverses, or contradicts later paper outcomes."),
            boundary: "This lab item explains evidence and proposals only. It has no order, broker-write, or live-capital authority."
        };
    });
    const paperForwardItem = {
        id: "paper-forward-outcomes",
        method_label: "Paper Forward",
        status_tone: paperOpenPositions.length || paperClosedTrades.length ? "online" : "pending",
        title: "Paper account outcomes",
        hypothesis: "Qadam compares actual paper holdings and closed trades with the hypotheses that produced them.",
        method: "Paper Forward",
        market_sleeve: "All sleeves",
        data_used: `${paperOpenPositions.length} open paper positions and ${paperClosedTrades.length} closed paper trades from the paper account mirror.`,
        result_so_far: `${paperOpenPositions.length} open paper positions and ${paperClosedTrades.length} closed paper trades are available for outcome comparison.`,
        proposal: "Use paper-forward outcomes as evidence before changing research priority.",
        proposal_status: "Pending Human Review",
        proposal_status_tone: "pending",
        proposal_reason: "Actual paper outcomes are inputs into the Strategy Feedback Model, not automatic instructions.",
        strategy_feedback_proposal: stage7LearningProposalRecord({}, {
            id: "paper-forward-proposal",
            market_sleeve: "All sleeves",
            proposal: "Compare paper outcomes with replay results before strategy changes.",
            would_change: "Learning review priority",
            reason: "Paper-forward results are the closest available proxy for real operating behaviour.",
            boundary: "Paper outcomes cannot mutate strategy without explicit human-governed review."
        }),
        quantum_review: meta.status || edge.quantum_pattern_review?.status || "not exported",
        what_would_confirm: "Closed trades and open-position behaviour agree with replay and source-price evidence.",
        what_would_invalidate: "Paper outcomes diverge from the hypothesis, show poor timing, or fail the risk/postmortem review.",
        boundary: "Paper Forward is a record of observed paper behaviour, not permission to trade."
    };
    const postmortemItem = {
        id: "postmortem-learning",
        method_label: "Postmortem",
        status_tone: paperClosedTrades.length ? "online" : "pending",
        title: "Outcome review and postmortems",
        hypothesis: "Closed paper outcomes are reviewed to decide what Qadam should keep, reduce, or reject in future research.",
        method: "Postmortem",
        market_sleeve: "All sleeves",
        data_used: `${paperClosedTrades.length} closed paper trades, edge memory records, proposal records, and quantum meta-review holds.`,
        result_so_far: `${modelNumber(promotion.promotion_review_ready_count, 0)} proposals are review-ready; ${modelNumber(promotion.promotion_gate_held_count, 0)} are held by promotion gates.`,
        proposal: "Keep learning proposals in the human review queue until evidence, quantum dependency, and governance gates pass.",
        proposal_status: "Pending Human Review",
        proposal_status_tone: "pending",
        proposal_reason: dashboardText(promotion.loop_level_decision || promotion.blocked_reason, "Promotion gates are holding automatic application."),
        strategy_feedback_proposal: stage7LearningProposalRecord(asArray(promotion.promotion_gate_decisions)[0] || {}, {
            id: "postmortem-proposal",
            market_sleeve: "All sleeves",
            proposal: "Retain or demote strategy hypotheses after postmortem review.",
            would_change: "Human-governed strategy learning",
            reason: "Postmortems decide whether a pattern deserved trust after the actual paper outcome.",
            boundary: "Postmortem output is review-only and cannot create broker authority."
        }),
        quantum_review: meta.status || edge.quantum_pattern_review?.status || "not exported",
        what_would_confirm: "Postmortems show the evidence chain improved timing, sizing discipline, or avoided a bad setup.",
        what_would_invalidate: "Postmortems show the thesis was coincidental, late, under-corroborated, or contradicted by outcome data.",
        boundary: "Postmortems can recommend learning actions, but cannot apply them automatically."
    };
    const trueBacktestItems = formalBacktest ? [{
        id: "true-backtest-export",
        method_label: "True Backtest",
        status_tone: "online",
        title: "Exported true backtest",
        hypothesis: dashboardText(formalBacktest.summary || formalBacktest.hypothesis, "Historical backtest results are exported for comparison."),
        method: "True Backtest",
        market_sleeve: dashboardText(formalBacktest.market_sleeve, "All sleeves"),
        data_used: dashboardText(formalBacktest.data_used || formalBacktest.dataset, "Historical market and source data."),
        result_so_far: dashboardText(formalBacktest.result || formalBacktest.status, "Backtest result exported."),
        proposal: "Compare backtest results with paper-forward and replay evidence.",
        proposal_status: "Pending Human Review",
        proposal_status_tone: "pending",
        proposal_reason: "Backtest evidence is comparative input only until reviewed.",
        strategy_feedback_proposal: stage7LearningProposalRecord({}, { id: "true-backtest-proposal", proposal: "Compare historical and paper-forward evidence.", market_sleeve: "All sleeves" }),
        quantum_review: meta.status || edge.quantum_pattern_review?.status || "not exported",
        what_would_confirm: "Backtest and paper-forward evidence agree on timing and drawdown behaviour.",
        what_would_invalidate: "Backtest results fail to survive replay, paper outcomes, or quantum meta-review.",
        boundary: "True backtests are evidence only and cannot bypass current paper gates."
    }] : [];
    const evaluationItems = [
        ...trueBacktestItems,
        ...replayItems,
        paperForwardItem,
        postmortemItem
    ];
    const readinessMap = patterns.slice(0, 5).map((pattern) => {
        const sleeve = stage7SleeveDisplayLabel(pattern.market_sleeve || pattern.sleeve_key || "Market sleeve");
        const missingCriteria = asArray(pattern.missing_criteria);
        const score = modelNumber(pattern.confidence_after_quantum_review, 0);
        return {
            sleeve,
            score,
            score_label: stage7Percent(score),
            status: pattern.trade_candidate_creation_allowed ? "Trade Candidate" : "Testing",
            condition: missingCriteria.length
                ? `Needs ${missingCriteria.map(stage7TitleFromKey).join(", ")}.`
                : "Needs fresh Signal Integrity, Risk, PaperOps, and Alpaca Paper acceptance.",
            tone: pattern.trade_candidate_creation_allowed ? "online" : "pending"
        };
    }).sort((a, b) => b.score - a.score || a.sleeve.localeCompare(b.sleeve));
    return {
        section_title: "Backtesting & Replay Lab",
        formal_backtest_available: Boolean(formalBacktest),
        formal_backtest_status: formalBacktest?.status || "not exported",
        replay_status: status.phase6_shadow_strategy_runner?.status || status.shadow_strategy_runner?.status || "not exported",
        paper_forward_status: daily.status || "not exported",
        strategy_feedback_status: updates.status || weights.status || "not exported",
        quantum_meta_review_status: meta.status || edge.quantum_pattern_review?.status || "not exported",
        candidate_pattern_count: modelNumber(daily.candidate_pattern_count || edge.pattern_ledger?.candidate_pattern_count, 0),
        validated_edge_count: modelNumber(daily.validated_edge_count || edge.pattern_ledger?.validated_edge_count, 0),
        hypothesis_thread_count: modelNumber(lifecycle.hypothesis_lifecycle_record_count || lifecycle.thread_count || lifecycle.source_hypothesis_count, 0),
        strategy_update_count: modelNumber(updates.strategy_update_count || updates.update_count || weights.strategy_weight_update_proposal_count, 0),
        promotion_review_ready_count: modelNumber(promotion.promotion_review_ready_count, 0),
        explanation: formalBacktest
            ? "Historical backtest results are exported and can be compared with paper-forward outcomes."
            : "No formal historical backtest artifact is exported yet. Qadam is using replay, paper-forward results, postmortems, edge memory, and strategy update proposals until a dedicated backtest artifact exists.",
        definitions: stage7LearningDefinitions(),
        evaluation_items: evaluationItems,
        strategy_feedback_model: {
            name: "Strategy Feedback Model",
            status: updates.status || weights.status || "not exported",
            inputs: [
                {
                    label: "Backtest results",
                    status: formalBacktest?.status || "not exported",
                    detail: formalBacktest ? "Historical simulation data is available for comparison." : "No formal true backtest artifact is exported yet."
                },
                {
                    label: "Scenario replays",
                    status: status.phase6_shadow_strategy_runner?.status || status.shadow_strategy_runner?.status || "replay only",
                    detail: `${replayItems.length} replay items compare source-price evidence against current Qadam logic.`
                },
                {
                    label: "Paper outcomes",
                    status: daily.status || "not exported",
                    detail: `${paperOpenPositions.length} open positions and ${paperClosedTrades.length} closed paper trades are visible.`
                },
                {
                    label: "Postmortems",
                    status: promotion.status || "not exported",
                    detail: `${modelNumber(promotion.promotion_review_ready_count, 0)} proposals ready for human-governed review; ${modelNumber(promotion.promotion_gate_held_count, 0)} held.`
                }
            ],
            generated_proposal_count: proposalQueue.length,
            proposal_queue: proposalQueue.length ? proposalQueue : [
                stage7LearningProposalRecord({}, {
                    id: "proposal-queue-empty",
                    market_sleeve: "All sleeves",
                    proposal: "No strategy feedback proposal has been exported yet.",
                    would_change: "Nothing",
                    reason: "The learning loop is waiting for more evidence.",
                    boundary: "No proposal authority exists without explicit review."
                })
            ],
            boundary: "Proposals are review-only. They do not change strategy weights, create trade candidates, submit paper orders, write brokers, or enable live capital."
        },
        readiness_map: readinessMap,
        cards: [
            { label: "Pattern engine", state: patternEngine.status || "not exported", summary: patternEngine.purpose || "Builds source-price features before quant review." },
            { label: "Edge memory", state: memory.status || "not exported", summary: memory.purpose || "Stores pattern evidence and outcome memory." },
            { label: "Hypothesis lifecycle", state: lifecycle.status || "not exported", summary: "Tracks whether hypotheses are observing, ready for review, refuted, or retained." },
            { label: "Strategy feedback model", state: updates.status || weights.status || "not exported", summary: "Compares hypotheses, paper outcomes, replay evidence, and proposed strategy weights." },
            { label: "Quantum meta-review", state: meta.status || edge.quantum_pattern_review?.status || "not exported", summary: meta.purpose || "Checks non-linear learning coherence before any proposal can be promoted." },
            { label: "Promotion gates", state: promotion.status || "not exported", summary: "Keeps strategy changes human-governed and prevents silent mutation." }
        ]
    };
}

function missionControlQuantMethodLabel(quantumOracle = {}, qctrl = {}, fireOpal = {}) {
    const oracleBackend = String(firstPresent(quantumOracle.latest_backend, quantumOracle.backend, "")).toLowerCase();
    const oracleMode = String(firstPresent(quantumOracle.latest_local_simulation_mode, quantumOracle.mode, "")).toLowerCase();
    const oracleMethod = `${oracleBackend} ${oracleMode}`;
    if (/classical|fallback|shadow|deterministic/.test(oracleMethod)) return "Classical Fallback (Deterministic)";
    const hardwareSubmitted = modelNumber(quantumOracle.hardware_submitted_count || qctrl.hardware_submitted_count || fireOpal.hardware_submitted_count, 0);
    const hardwareText = String(firstPresent(quantumOracle.latest_backend, quantumOracle.provider, qctrl.backend, fireOpal.backend, fireOpal.status, "")).toLowerCase();
    if (hardwareSubmitted > 0 && /ibm|q-?ctrl|hardware|qiskit|runtime/.test(hardwareText)) return "IBM / Q-CTRL Hardware";
    if (/fire\s*opal|fire_opal|optimization|optimisation/.test(hardwareText) && !/device_probe|submitted|readiness/.test(hardwareText)) return "Fire Opal Optimisation";
    return "Classical Fallback (Deterministic)";
}

function missionControlTeamRoleLabel(role = {}) {
    const key = String(role.key || role.label || "").toLowerCase();
    const labels = {
        safety_policy: "Risk Desk",
        risk_agent: "Risk Desk",
        signal_integrity_gate: "Risk Desk",
        paper_demo_state: "Paper Trading Desk",
        broker_reconciliation: "Paper Trading Desk",
        execution_adapter_status: "Paper Trading Desk"
    };
    return labels[key] || role.label || role.owner || "Qadam role";
}

function stage7RoleStatusLabel(status, currentTask = "") {
    const text = `${status || ""} ${currentTask || ""}`.toLowerCase();
    if (/idle|standby|no active/.test(text)) return "Idle";
    if (/review|pending|blocked|deferred|monitor|waiting|queued/.test(text)) return "Monitoring";
    if (/online|ok|ready|active|connected|certified|enabled|configured|available/.test(text)) return "Active";
    return "Monitoring";
}

function stage7RoleStatusTone(statusLabel) {
    if (statusLabel === "Active") return "online";
    if (statusLabel === "Idle") return "pending";
    return "pending";
}

function stage7AuthorityLabel(authority = "") {
    const text = String(authority || "").toLowerCase();
    if (/guarded_paper|execute_paper|paper_only/.test(text)) return "Execute Paper Only";
    if (/human|review|write_blocked|approval|governed/.test(text)) return "Human Governed";
    if (/non_executable|propose|shadow|challenge/.test(text)) return "Propose Only";
    return "Read Only";
}

function stage7RoleCannotDo(key, authorityLevel) {
    const shared = [
        "enable live capital",
        "call live broker endpoints",
        "bypass Qadam's paper safety gates"
    ];
    const specific = {
        coo: ["invent trades by itself", "override risk or execution policy", "send operational commands from the dashboard"],
        research_analyst: ["place trades", "approve a hypothesis", "change strategy weights"],
        strategy_lead: ["submit orders", "override the Head of Quant or Risk Desk", "self-apply strategy changes"],
        head_of_quant: ["place trades", "approve risk sizing", "claim hardware execution when the run used fallback"],
        risk_desk: ["create a thesis", "submit broker orders directly", "ignore idempotency or account reconciliation"],
        paper_trading_desk: ["trade live capital", "submit outside the guarded Alpaca Paper route", "change strategy logic"],
        learning_review: ["mutate strategy weights silently", "approve its own proposals", "create broker writes"]
    };
    const authority = authorityLevel === "Execute Paper Only"
        ? ["execute outside approved paper-only authority"]
        : [`act beyond ${authorityLevel.toLowerCase()} authority`];
    return [...(specific[key] || []), ...authority, ...shared];
}

function stage7QuantRunLog(quantumOracle = {}, qctrl = {}, fireOpal = {}, quantMethodLabel = "Classical Fallback (Deterministic)") {
    const oracleBackend = dashboardText(firstPresent(quantumOracle.backend, quantumOracle.latest_backend), "not exported");
    const oracleMode = dashboardText(firstPresent(quantumOracle.mode, quantumOracle.latest_local_simulation_mode), "not exported");
    const qctrlStatus = dashboardText(qctrl.status, "not exported");
    const fireOpalStatus = dashboardText(fireOpal.status, "not exported");
    return [
        {
            label: "Latest review method",
            method: quantMethodLabel,
            detail: `Latest exported oracle backend is ${oracleBackend} with mode ${oracleMode}.`
        },
        {
            label: "Q-CTRL product access",
            method: quantMethodLabel,
            detail: `Q-CTRL status is ${qctrlStatus}; this does not by itself mean hardware execution.`
        },
        {
            label: "IBM / Fire Opal device path",
            method: quantMethodLabel,
            detail: `IBM / Fire Opal status is ${fireOpalStatus}; Qadam only reports hardware when the actual run method confirms it.`
        }
    ];
}

function stage7FindRawTeamRole(rawRoles = [], keys = []) {
    const wanted = keys.map((key) => String(key || "").toLowerCase());
    return asArray(rawRoles).find((role) => {
        const roleKey = String(role.key || "").toLowerCase();
        const roleLabel = String(role.label || "").toLowerCase();
        const roleOwner = String(role.owner || "").toLowerCase();
        return wanted.some((key) => roleKey === key || roleLabel.includes(key) || roleOwner.includes(key));
    }) || {};
}

function stage7BuildTeamRole(config = {}, rawRoles = [], context = {}) {
    const raw = stage7FindRawTeamRole(rawRoles, config.raw_keys || [config.key]);
    const currentTask = dashboardText(raw.current_process || config.current_task, "Monitoring the current paper-fund snapshot.");
    const statusLabel = stage7RoleStatusLabel(raw.status || config.status, currentTask);
    const authorityLevel = stage7AuthorityLabel(raw.authority || config.authority);
    const quantMethodLabel = config.key === "head_of_quant"
        ? context.quant_method_label || raw.quant_method_label || "Classical Fallback (Deterministic)"
        : null;
    return {
        key: config.key,
        label: config.label,
        owner: config.owner,
        status_label: statusLabel,
        status_tone: stage7RoleStatusTone(statusLabel),
        raw_status: dashboardText(raw.status || config.status, "not exported"),
        job_description: dashboardText(config.job_description || raw.role, "Role description not exported."),
        full_description: dashboardText(raw.role || config.full_description || config.job_description, "Role description not exported."),
        current_task: currentTask,
        authority_level: authorityLevel,
        cannot_do: stage7RoleCannotDo(config.key, authorityLevel),
        quant_method_label: quantMethodLabel,
        quant_run_log: config.key === "head_of_quant"
            ? stage7QuantRunLog(context.quantum_oracle, context.qctrl, context.fire_opal, quantMethodLabel)
            : []
    };
}

