function firstDefined(...values) {
    return values.find((value) => value !== undefined && value !== null && value !== "");
}

function dashboardPortfolioModel(status = {}) {
    const canonical = status.dashboard_portfolio || {};
    const qsase = status.qsase_dashboard || {};
    const qsasePortfolio = qsase.dashboard_portfolio || {};
    const sections = qsase.sections || {};
    const qsaseValue = sections.portfolio_value || {};
    const qsaseCurrent = sections.current_portfolio || {};
    const capital = status.capital || {};
    const missionPortfolio = status.mission_control?.portfolio || {};
    const equityCurve = asArray(
        firstDefined(canonical.equity_curve, qsasePortfolio.equity_curve, qsaseValue.series, capital.equity_curve)
    );
    const latestCurvePoint = canonical.latest_curve_point
        || qsasePortfolio.latest_curve_point
        || equityCurve.at(-1)
        || {};
    const positions = asArray(firstDefined(canonical.positions, qsasePortfolio.positions, qsaseCurrent.rows, capital.open_positions));
    const currentValue = modelNumber(firstDefined(
        canonical.current_value_gbp,
        qsasePortfolio.current_value_gbp,
        qsaseValue.current_value_gbp,
        latestCurvePoint.portfolio_value,
        latestCurvePoint.equity_gbp,
        capital.equity_gbp,
        capital.current_balance_gbp,
        missionPortfolio.current_balance_gbp
    ), 0);
    const cash = modelNumber(firstDefined(canonical.cash_gbp, qsasePortfolio.cash_gbp, capital.cash_gbp, latestCurvePoint.cash), 0);
    const starting = modelNumber(firstDefined(
        canonical.starting_balance_gbp,
        qsasePortfolio.starting_balance_gbp,
        capital.starting_balance_gbp,
        missionPortfolio.starting_balance_gbp,
        equityCurve[0]?.portfolio_value,
        equityCurve[0]?.equity_gbp
    ), currentValue);
    const realized = modelNumber(firstDefined(canonical.realized_pnl_gbp, qsasePortfolio.realized_pnl_gbp, capital.realized_pnl_gbp), 0);
    const unrealized = modelNumber(firstDefined(canonical.unrealized_pnl_gbp, qsasePortfolio.unrealized_pnl_gbp, capital.unrealized_pnl_gbp), 0);
    const totalPnl = modelNumber(firstDefined(canonical.total_pnl_gbp, qsasePortfolio.total_pnl_gbp, capital.total_pnl_gbp), realized + unrealized);
    const currency = normaliseCurrencyCode(firstDefined(
        canonical.display_currency,
        canonical.currency,
        qsasePortfolio.display_currency,
        qsasePortfolio.currency,
        qsaseValue.display_currency,
        capital.display_currency,
        capital.currency,
        latestCurvePoint.display_currency,
        "GBP"
    ));
    const portfolioConsistency = canonical.portfolio_consistency || qsasePortfolio.portfolio_consistency || {
        status: "unknown",
        value_delta: null,
        latest_curve_value: firstDefined(latestCurvePoint.portfolio_value, latestCurvePoint.equity_gbp, qsaseValue.latest_value)
    };
    return {
        ...qsasePortfolio,
        ...canonical,
        artifact_type: canonical.artifact_type || qsasePortfolio.artifact_type || "dashboard_portfolio_canonical_contract",
        status: canonical.status || qsasePortfolio.status || "dashboard_portfolio_missing",
        current_value_gbp: currentValue,
        current_value: currentValue,
        starting_balance_gbp: starting,
        cash_gbp: cash,
        exposure_gbp: modelNumber(firstDefined(canonical.exposure_gbp, qsasePortfolio.exposure_gbp, currentValue - cash), 0),
        realized_pnl_gbp: realized,
        unrealized_pnl_gbp: unrealized,
        total_pnl_gbp: totalPnl,
        open_position_count: modelNumber(firstDefined(canonical.open_position_count, qsasePortfolio.open_position_count, qsaseCurrent.position_count, positions.length, capital.open_position_count), positions.length),
        open_order_count: modelNumber(firstDefined(canonical.open_order_count, qsasePortfolio.open_order_count, capital.open_order_count), 0),
        order_count: modelNumber(firstDefined(canonical.order_count, qsasePortfolio.order_count, capital.order_count), asArray(capital.orders).length),
        closed_trade_count: modelNumber(firstDefined(canonical.closed_trade_count, qsasePortfolio.closed_trade_count, capital.closed_trade_count), 0),
        paper_order_count: modelNumber(firstDefined(canonical.paper_order_count, qsasePortfolio.paper_order_count, capital.paper_order_count), 0),
        display_currency: currency,
        equity_curve: equityCurve,
        latest_curve_point: latestCurvePoint,
        positions,
        portfolio_consistency: portfolioConsistency,
        broker_mirror_freshness: canonical.broker_mirror_freshness || qsasePortfolio.broker_mirror_freshness || {},
        public_snapshot_freshness: canonical.public_snapshot_freshness || qsasePortfolio.public_snapshot_freshness || {},
        boundary: canonical.boundary || qsasePortfolio.boundary || "Read-only paper account mirror."
    };
}

function buildQadamDashboardViewModels(status = {}, source = {}) {
    const qsaseDashboard = buildQsaseDashboardModel(status);
    const sources = buildSourcesModel(status);
    const trades = buildTradesModel(status, { sources_model: sources });
    const reasoning = buildReasoningModel(status);
    const performance = buildPerformanceModel(status);
    const governance = buildGovernanceModel(status);
    const systemConnectivity = buildSystemConnectivityModel(status);
    const edgeTracker = buildEdgeTrackerModel(status);
    const operations = buildOperationsModel(status, source, {
        system_connectivity_model: systemConnectivity,
        governance_model: governance
    });
    const sharedModels = {
        sources_model: sources,
        trades_model: trades,
        reasoning_model: reasoning,
        performance_model: performance,
        system_connectivity_model: systemConnectivity,
        operations_model: operations,
        governance_model: governance,
        edge_tracker_model: edgeTracker
    };
    const overview = buildOverviewModel(status, source, operations, sharedModels);
    const safetyStrip = buildDashboardSafetyStripModel(status, {
        operations_model: operations,
        performance_model: performance
    });
    const founderContract = buildFounderContractModel(status, source, sharedModels);
    const stage7Visibility = buildStage7VisibilityModel(status, {
        ...sharedModels,
        overview_model: overview,
        safety_strip_model: safetyStrip,
        founder_contract_model: founderContract
    });
    const modelGraph = {
        contract: "single_shared_dashboard_view_model_bundle",
        build_order: [
            "founder_contract_model",
            "qsase_dashboard_model",
            "stage7_visibility_model",
            "sources_model",
            "trades_model",
            "reasoning_model",
            "performance_model",
            "governance_model",
            "edge_tracker_model",
            "system_connectivity_model",
            "operations_model",
            "overview_model",
            "safety_strip_model"
        ],
        shared_dependencies: {
            founder_contract_model: ["mission_control"],
            stage7_visibility_model: [
                "founder_contract_model",
                "overview_model",
                "sources_model",
                "trades_model",
                "reasoning_model",
                "performance_model",
                "operations_model",
                "edge_tracker_model"
            ],
            trades_model: ["sources_model"],
            operations_model: ["system_connectivity_model", "governance_model"],
            edge_tracker_model: ["edge_tracker"],
            overview_model: [
                "sources_model",
                "trades_model",
                "reasoning_model",
                "performance_model",
                "operations_model",
                "system_connectivity_model"
            ],
            safety_strip_model: ["operations_model", "performance_model"]
        },
        renderer_entrypoint: "renderQadamDashboardStatus",
        renderer_uses_shared_bundle: true
    };
    return {
        schema_version: "dashboard_view_models.v1",
        model_contract_version: "dashboard_view_models.cc5.founder_contract.v1",
        generated_at: status.generated_at || null,
        status_source: source?.key || "unknown",
        public_safe: true,
        authority_boundary: "View models are read-only projections of sanitized dashboard status. They cannot grant trading, broker, provider, Telegram, learning-write, or live-capital authority.",
        model_graph: modelGraph,
        founder_contract_model: founderContract,
        qsase_dashboard_model: qsaseDashboard,
        stage7_visibility_model: stage7Visibility,
        edge_tracker_model: edgeTracker,
        safety_strip_model: safetyStrip,
        overview_model: overview,
        trades_model: trades,
        sources_model: sources,
        reasoning_model: reasoning,
        performance_model: performance,
        system_connectivity_model: systemConnectivity,
        operations_model: operations,
        governance_model: governance,
        safety_model: {
            authority_flags: operations.safety.authority_flags,
            readiness_warnings: operations.safety.readiness_warnings,
            authority_unchanged: operations.safety.authority_flags.length === 0,
            ui_inferred_readiness_detected: operations.safety.readiness_warnings.includes("ui_inferred_readiness_detected"),
            false_proof_credit_detected: operations.safety.readiness_warnings.includes("false_phase7_proof_credit"),
            missing_source_quorum_detected: operations.safety.readiness_warnings.includes("missing_source_quorum")
        }
    };
}

function statusFetchHeaders(source, session) {
    if (!source.requiresAuth || !session?.access_token) return {};
    return { Authorization: `Bearer ${session.access_token}` };
}

async function fetchDashboardStatus(session) {
    const failures = [];
    for (const source of STATUS_SOURCES) {
        try {
            const response = await fetch(`${source.url}?t=${Date.now()}`, {
                cache: "no-store",
                headers: statusFetchHeaders(source, session)
            });
            if (!response.ok) {
                failures.push(`${source.key}:${response.status}`);
                continue;
            }
            return {
                source: { ...source, prior_failures: failures.slice() },
                status: await response.json()
            };
        } catch (error) {
            failures.push(`${source.key}:${error.message || "fetch failed"}`);
        }
    }
    throw new Error(`all status sources failed: ${failures.join(", ")}`);
}

function sourceSummary(status) {
    const watching = asArray(status.watching);
    const displaySources = watching.map((source) => ({
        ...source,
        core: sourceIsCore(source),
        display_status: sourceDisplayStatus(source),
        requires_action: sourceRequiresAction(source)
    }));
    const counts = countBy(displaySources, "display_status");
    const coreSources = displaySources.filter((source) => source.core);
    const missingCredentialCount = displaySources.filter(
        (source) => source.core && source.credential_status === "missing"
    ).length;
    return [
        renderMetric("Sources", watching.length),
        renderMetric("Core OK", `${coreSources.filter((source) => source.display_status === "ok").length}/${coreSources.length}`),
        renderMetric("Needs attention", displaySources.filter((source) => source.requires_action).length),
        renderMetric("Waiting", counts.waiting || 0),
        renderMetric("Optional", counts.optional || 0),
        renderMetric("Local-only", counts["local only"] || 0),
        renderMetric("Required not configured", missingCredentialCount),
        renderMetric("Research usable", watching.filter(sourceUsableForResearch).length),
        renderMetric("Signal review eligible", watching.filter(sourceEligibleForSignalReview).length),
        renderMetric("Order authority", watching.filter(sourceCanAuthorizeOrders).length)
    ].join("");
}

function systemMapNode(module, index) {
    const details = flowNodeDetails(module);
    return `
        <article class="flow-node system-map-node">
            <div class="node-topline">
                ${renderStatusPill(module.status)}
                <span>${String(index + 1).padStart(2, "0")} · ${htmlText(details.role, module.owner || "Qadam desk")}</span>
            </div>
            <h3>${htmlText(module.label, module.key)}</h3>
            <p class="flow-summary">${htmlText(module.current_process)}</p>
            <dl class="node-facts">
                <div>
                    <dt>Input</dt>
                    <dd>${htmlText(details.input)}</dd>
                </div>
                <div>
                    <dt>Output</dt>
                    <dd>${htmlText(details.output)}</dd>
                </div>
            </dl>
        </article>
    `;
}

function systemMapConnector(label) {
    return `<div class="flow-connector" aria-hidden="true"><span>${htmlText(label)}</span></div>`;
}

function systemMapLane(lane, laneIndex) {
    const nodeHtml = lane.nodes
        .map((node, nodeIndex) => {
            const globalIndex = lane.offset + nodeIndex;
            const connector = nodeIndex < lane.nodes.length - 1
                ? systemMapConnector(node.handoff || "passes state")
                : "";
            return `${systemMapNode(node, globalIndex)}${connector}`;
        })
        .join("");

    return `
        <section class="flow-lane ${statusClass(lane.tone || "neutral")}">
            <header class="flow-lane-header">
                <span>${String(laneIndex + 1).padStart(2, "0")}</span>
                <div>
                    <h3>${htmlText(lane.title)}</h3>
                    <p>${htmlText(lane.summary)}</p>
                </div>
            </header>
            <div class="flow-lane-track">${nodeHtml}</div>
            <div class="lane-handoff"><span>${htmlText(lane.handoff)}</span></div>
        </section>
    `;
}

