function renderContractStrategyNarrative(contract = {}) {
    const strategy = contract.strategy || {};
    const sources = contract.sources || {};
    const trades = contract.trades || {};
    const thinking = contract.thinking || {};
    const activeLens = strategy.active_lens || {};
    const nativeEdge = strategy.native_edge || {};
    const strategyFamilies = asArray(strategy.fit_matrix).length ? asArray(strategy.fit_matrix) : asArray(strategy.strategy_families);
    const topCandidate = asArray(trades.top_candidates)[0] || asArray(trades.board).find((item) => item.state === "candidate") || {};
    const hasGatedCandidate = Boolean(topCandidate.instrument || topCandidate.label || topCandidate.state);
    const sourceSentence = `${modelNumber(sources.online, 0)}/${modelNumber(sources.total, 0)} sources are online, ${modelNumber(sources.research_usable, 0)} can shape research context, and ${modelNumber(sources.signal_review_eligible, 0)} can influence signal review.`;
    const thinkingSentence = `${modelNumber(thinking.research_goal_active_count, 0)} research observations, ${modelNumber(thinking.hypothesis_count, 0)} hypotheses, and ${modelNumber(thinking.evidence_packet_count, 0)} evidence packets are feeding the current review.`;
    const tradeSentence = hasGatedCandidate
        ? "A gated candidate exists, but its row identity and lineage stay in Trades until source, risk, and paper-account gates pass."
        : "No leading candidate is strong enough to summarize as an imminent paper order in this snapshot.";
    return `
        <div class="strategy-narrative-shell ${statusClass(strategy.posture || activeLens.status || "online")}" data-cc5-contract-source="mission_control">
            <article class="strategy-narrative-lead">
                <span>What Qadam is choosing now</span>
                <h3>${htmlText(nativeEdge.name || activeLens.name || strategy.posture || "Evidence-gated paper strategy")}</h3>
                <p>${htmlText(nativeEdge.thesis || strategy.why || "Qadam reviews catalyst setups through source, model, risk, and paper-route checks.")}</p>
                <p>${htmlText(sourceSentence)} ${htmlText(thinkingSentence)} ${htmlText(tradeSentence)}</p>
            </article>
            ${renderStrategySummaryStrip(strategy, strategyFamilies)}
            <div class="strategy-narrative-grid">
                <article>
                    <span>Current route</span>
                    <strong>${htmlText((nativeEdge.decision_spine || strategy.decision_chain || []).slice(0, 7).join(" -> ") || "Catalyst -> source quorum -> paper risk -> guarded paper route.")}</strong>
                </article>
                <article>
                    <span>Strategy lens</span>
                    <strong>${htmlText(activeLens.name || "Second-order AI infrastructure beneficiary lens")}</strong>
                    <small>${htmlText(activeLens.gating_role || "comparison input only, not a trade trigger.")}</small>
                </article>
                <article>
                    <span>Boundary</span>
                    <strong>${htmlText(strategy.boundary || "Strategy remains non-executable until Signal Integrity and Risk Agent gates pass.")}</strong>
                </article>
            </div>
        </div>
    `;
}

function renderContractStrategyUniverse(contract = {}) {
    const strategy = contract.strategy || {};
    const activeLens = strategy.active_lens || {};
    const strategyFamilies = asArray(strategy.fit_matrix).length ? asArray(strategy.fit_matrix) : asArray(strategy.strategy_families);
    const familyCount = strategy.strategy_family_count || strategyFamilies.length || asArray(strategy.universe).length || 0;
    const qualifiedCount = strategy.qualified_strategy_family_count || strategyFamilies.filter((family) => family.qualified_setup).length || 0;
    const posture = strategy.posture || activeLens.status || "online";
    return `
        <div class="strategy-universe-shell ${statusClass(posture)}" data-cc5-contract-source="mission_control">
            <div class="overview-section-head">
                <span>Strategy Universe</span>
                <strong>${htmlText(familyCount)} families · ${htmlText(qualifiedCount)} qualified now</strong>
            </div>
            ${renderContractStrategyNarrative(contract)}
            ${renderContractStrategyBlock(contract)}
        </div>
    `;
}

function renderContractPortfolioBlock(portfolio = {}) {
    const chartPoints = asArray(portfolio.equity_curve);
    const freshnessStatus = portfolio.mirror_freshness_status || portfolio.mirror_freshness || "unknown";
    const freshnessTone = freshnessStatus === "fresh" || freshnessStatus === "live"
        ? "online"
        : (freshnessStatus === "stale" || freshnessStatus === "unknown" ? "degraded" : "pending");
    const freshnessLabel = `${freshnessStatus} mirror`;
    const closedTarget = `${modelNumber(portfolio.closed_trade_count, 0)}/${modelNumber(portfolio.maturity_closed_trade_target, 100)}`;
    if (!chartPoints.length) {
        return `
            <div class="overview-capacity-chart-card degraded" data-cc6-real-portfolio-timeline="missing" data-cc5-contract-source="mission_control">
                <div class="overview-section-head">
                    <span>Real portfolio timeline</span>
                    <strong>No exported equity-curve points</strong>
                    ${renderInlineBadge(freshnessLabel, freshnessTone)}
                </div>
                <p class="mini">The dashboard is not fabricating portfolio history. Export capital.equity_curve to render the paper-account line.</p>
                <div class="overview-capacity-summary">
                    ${renderMetric("Balance", formatMoney(portfolio.balance_gbp))}
                    ${renderMetric("Delta", formatPercent(portfolio.delta_pct))}
                    ${renderMetric("Closed/target", closedTarget)}
                    ${renderMetric("Timeline source", portfolio.timeline_source || "missing")}
                </div>
            </div>
        `;
    }
    const stats = paperAccountEquityStats(chartPoints);
    const width = 520;
    const height = 150;
    const left = 66;
    const right = 16;
    const top = 18;
    const bottom = 28;
    const plotWidth = width - left - right;
    const plotHeight = height - top - bottom;
    const rawMin = stats.min;
    const rawMax = stats.max;
    const range = rawMax - rawMin;
    const padding = range > 0 ? range * 0.18 : Math.max(10, Math.abs(rawMax || 1000) * 0.01);
    const min = rawMin - padding;
    const max = rawMax + padding;
    const yFor = (value) => top + ((max - value) / (max - min || 1)) * plotHeight;
    const xFor = (index) => left + (chartPoints.length <= 1 ? plotWidth / 2 : (index / (chartPoints.length - 1)) * plotWidth);
    const path = chartPoints
        .map((point, index) => `${index ? "L" : "M"} ${xFor(index).toFixed(2)} ${yFor(point.equity_gbp).toFixed(2)}`)
        .join(" ");
    const lineTone = stats.change >= 0 ? "online" : "blocked";
    return `
        <div class="overview-capacity-chart-card ${statusClass(freshnessTone)}" data-cc6-real-portfolio-timeline="capital.equity_curve" data-cc5-contract-source="mission_control">
            <div class="overview-section-head">
                <span>Real portfolio timeline</span>
                <strong>${chartPoints.length} live points · ${htmlText(portfolio.timeline_source || "capital.equity_curve")}</strong>
                ${renderInlineBadge(freshnessLabel, freshnessTone)}
            </div>
            <svg class="overview-capacity-line" viewBox="0 0 ${width} ${height}" role="img" aria-label="Paper account portfolio value line" preserveAspectRatio="none" data-paper-capacity-line>
                <title>Paper account equity curve from ${literalHtmlText(portfolio.timeline_source || "capital.equity_curve")}</title>
                <desc>${literalHtmlText(`${chartPoints.length} real points, latest balance ${formatMoney(portfolio.balance_gbp)}, ${freshnessLabel}.`)}</desc>
                <line class="chart-grid-line" x1="${left}" y1="${height - bottom}" x2="${width - right}" y2="${height - bottom}"></line>
                <line class="chart-grid-line muted" x1="${left}" y1="${yFor(stats.max).toFixed(2)}" x2="${width - right}" y2="${yFor(stats.max).toFixed(2)}"></line>
                <line class="chart-grid-line muted" x1="${left}" y1="${yFor(stats.min).toFixed(2)}" x2="${width - right}" y2="${yFor(stats.min).toFixed(2)}"></line>
                <path class="paper-equity-line ${statusClass(lineTone)}" d="${path}"></path>
                <text class="chart-axis-label" x="4" y="${yFor(stats.max).toFixed(2)}">${literalHtmlText(formatMoney(stats.max))}</text>
                <text class="chart-axis-label" x="4" y="${yFor(stats.min).toFixed(2)}">${literalHtmlText(formatMoney(stats.min))}</text>
                <text class="chart-axis-label chart-axis-last" x="${width - right}" y="${height - 8}">${literalHtmlText(formatTime(chartPoints.at(-1)?.observed_at || portfolio.observed_at))}</text>
            </svg>
            <div class="overview-capacity-summary">
                ${renderMetric("Balance", formatMoney(portfolio.balance_gbp))}
                ${renderMetric("Delta", formatPercent(portfolio.delta_pct))}
                ${renderMetric("Drawdown", formatPercent(portfolio.drawdown_pct))}
                ${renderMetric("Realized", formatMoney(portfolio.realized_pnl_gbp))}
                ${renderMetric("Unrealized", formatMoney(portfolio.unrealized_pnl_gbp))}
                ${renderMetric("Closed/target", closedTarget)}
                ${renderMetric("Timeline", `${chartPoints.length} live points`)}
            </div>
        </div>
    `;
}

