        `${modelNumber(counts.candidate, 0)} candidates`,
        `${modelNumber(counts.open, 0)} open`,
        `${modelNumber(counts.closed, 0)} closed`,
        `${modelNumber(counts.postmortem_due, 0)} postmortems due`
