        strategy_rank: dashboardText(sleeve.strategy_rank, "not ranked"),
        akber_gate: dashboardText(sleeve.akber_gate, "Context"),
        recent_movement_direction: dashboardText(sleeve.recent_movement_direction, "flat"),
