function renderOverviewFirstScreen(viewModels) {
    const contract = viewModels?.founder_contract_model;
    if (!contract) return;

    const statusRail = dashboardQuery("[data-overview-status-rail]");
    if (statusRail) {
        const source = contract.sources || {};
        const portfolio = contract.portfolio || {};
        statusRail.innerHTML = [
            { label: "Sources", value: `${source.online}/${source.total}`, tone: source.degraded || source.missing_credentials ? "degraded" : "online" },
            { label: "Research observations", value: contract.thinking?.research_goal_active_count || 0, tone: contract.thinking?.status || "pending" },
            { label: "Paper value", value: formatMoney(portfolio.balance_gbp), tone: portfolio.mirror_freshness_status === "stale" ? "degraded" : "online" },
            { label: "Trade candidates", value: contract.trades?.lifecycle_counts?.candidate || 0, tone: contract.trades?.state || "pending" }
        ].map(renderOverviewChip).join("");
    }

    const portfolioHeroTarget = dashboardQuery("[data-overview-portfolio-hero]");
    if (portfolioHeroTarget) {
        portfolioHeroTarget.innerHTML = renderContractPortfolioHero(contract.portfolio || {});
    }

    const missionBriefTarget = dashboardQuery("[data-overview-mission-brief]");
    if (missionBriefTarget) {
        missionBriefTarget.innerHTML = renderContractMissionSnapshot(contract);
    }

    const strategyNarrativeTarget = dashboardQuery("[data-overview-strategy-narrative]");
    if (strategyNarrativeTarget) {
        strategyNarrativeTarget.innerHTML = renderContractStrategyUniverse(contract);
    }

    const paperTradeState = dashboardQuery("[data-overview-paper-trade-state]");
    if (paperTradeState) {
        paperTradeState.innerHTML = renderContractPaperTradeState(contract);
    }

    const metrics = dashboardQuery("[data-overview-metrics]");
    if (metrics) {
        metrics.innerHTML = "";
    }

    setText("[data-overview-lifecycle-summary]", contract.trades?.summary || "Mission Control trade lifecycle is loaded.");
    const lifecycle = dashboardQuery("[data-overview-lifecycle]");
    if (lifecycle) {
        lifecycle.innerHTML = Object.entries(contract.trades?.lifecycle_counts || {})
            .map(([label, count], index) => renderOverviewLifecycleItem({ label: label.replaceAll("_", " "), count, tone: count ? "online" : "pending" }, index))
            .join("");
    }

    const controlPlane = dashboardQuery("[data-overview-control-plane]");
    if (controlPlane) {
        controlPlane.innerHTML = renderContractControlPlane(contract);
    }

    const sourceSummary = dashboardQuery("[data-overview-source-summary]");
    if (sourceSummary) {
        sourceSummary.innerHTML = renderContractSourceSummary(contract.sources || {});
    }

    const edgeTracker = dashboardQuery("[data-overview-edge-tracker]");
    if (edgeTracker) {
        edgeTracker.innerHTML = renderOverviewEdgeTracker(viewModels.overview_model?.edge_tracker || viewModels.edge_tracker_model || {});
    }

    const nextLinks = dashboardQuery("[data-overview-next-links]");
    if (nextLinks) {
        nextLinks.innerHTML = "";
    }
}

